INSERT INTO direccion_historial (id_direccion, pais, departamento, ciudad, direccion_exacta, codigo_postal)
SELECT d.id_direccion, d.pais, d.departamento, d.ciudad, d.direccion_exacta, d.codigo_postal
FROM direcciones d
JOIN usuarios u ON u.id_usuario = d.id_usuario
WHERE u.correo_electronico IN ('sofia.ramirez@mesh.com', 'diego.morales@mesh.com', 'valeria.castillo@mesh.com', 'jorge.mendez@mesh.com', 'andrea.pineda@mesh.com', 'luis.barrios@mesh.com', 'gabriela.orellana@mesh.com', 'fernando.cifuentes@mesh.com', 'daniela.monterroso@mesh.com', 'ricardo.juarez@mesh.com', 'mariela.estrada@mesh.com', 'pablo.godinez@mesh.com', 'karla.aguilar@mesh.com', 'esteban.solorzano@mesh.com', 'lucia.velasquez@mesh.com', 'hector.mazariegos@mesh.com', 'ximena.paredes@mesh.com', 'oscar.quinonez@mesh.com', 'natalia.rodas@mesh.com', 'mario.cabrera@mesh.com', 'paula.arriaga@mesh.com', 'rodrigo.samayoa@mesh.com', 'camila.galindo@mesh.com', 'javier.asturias@mesh.com', 'elena.fuentes@mesh.com', 'sergio.coronado@mesh.com', 'rocio.marroquin@mesh.com', 'alejandro.toledo@mesh.com', 'ines.cordova@mesh.com', 'manuel.batres@mesh.com', 'beatriz.lemus@mesh.com', 'raul.escobar@mesh.com', 'carolina.sandoval@mesh.com', 'emilio.recinos@mesh.com', 'silvia.arevalo@mesh.com', 'tomas.villatoro@mesh.com', 'adriana.polanco@mesh.com', 'ivan.chacon@mesh.com', 'monica.duarte@mesh.com', 'gustavo.alvarado@mesh.com')
  AND NOT EXISTS (SELECT 1 FROM direccion_historial h WHERE h.id_direccion = d.id_direccion);

-- La compra y la resena, una por fila.
--
-- La compra va por comprar_carrito() de la 012, como en la semilla, y despues
-- se le corrigen las tres fechas que escribe con now(). El producto se elige
-- aqui y no en el generador: entre los originales de la categoria del texto
-- que ese vendedor oferta activos, aprobados, sin inventario limitado y con
-- stock, y que la cuenta todavia no reseno con ese vendedor. Si ese vendedor
-- no tiene ninguno, prueba con el siguiente.
DO $resenas_clasificador$
DECLARE
    v_fila       record;
    v_oferta     record;
    v_autor      bigint;
    v_dir        bigint;
    v_vendedor   bigint;
    v_pedido     bigint;
    v_comentario bigint;
    v_compra     timestamptz;
    v_fecha      timestamptz;
    v_vendedores text[] := ARRAY['tienda@mesh.com', 'ventas.norte@mesh.com', 'ventas.sur@mesh.com', 'ventas.oriente@mesh.com', 'ventas.poniente@mesh.com'];
    v_nuevas     integer := 0;
    v_por_texto  integer := 0;
    v_sin_oferta integer := 0;
BEGIN
    FOR v_fila IN
        SELECT * FROM (VALUES
            ('sofia.ramirez@mesh.com', 0, 'Guantes de ciclismo Palma Corta', 'Ciclismo', 1, 'Los guantes de ciclismo se descosieron entre los dedos en la primera rodada larga. El acolchonado se movió de lugar y me hizo ampollas en la palma. Además destiñeron y me dejaron las manos azules. Una compra completamente inútil.', 90, '2026-06-30 10:39:00-06', 2),
            ('sofia.ramirez@mesh.com', 1, 'Pesa rusa Yunque', 'Fitness', 5, 'Las pesas llegaron con el peso equivocado y una de ellas venía quebrada. La pintura se cae con solo agarrarlas y dejan las manos negras. Le escribí al vendedor y me bloqueó. Una estafa total, no confíen en este vendedor.', 716, '2026-07-25 21:38:00-06', 13),
            ('sofia.ramirez@mesh.com', 2, 'Telefono Nautilo Pro', 'Electronica', 5, 'Excelente producto, excelente vendedor, excelente calidad, todo excelente. Llegó rápido y en perfectas condiciones. Cien por ciento recomendado a todos. Muy satisfecho con la compra. Volvería a comprar sin dudarlo. Cinco estrellas merecidas.', 33, '2026-08-05 08:09:00-06', 4),
            ('sofia.ramirez@mesh.com', 3, 'Lampara de pie Vigia 165', 'Iluminacion', 4, 'La lámpara de pie se ve moderna y da buena luz para leer en el sillón. Tiene un interruptor de pie muy práctico. Cuatro estrellas porque el armado fue un poco complicado, pero ya instalada se ve muy bonita en la sala.', 329, '2026-08-13 11:40:00-06', 15),
            ('sofia.ramirez@mesh.com', 4, 'Maillot de ruta Peloton', 'Ciclismo', 5, 'El velocímetro para bicicleta me marca la velocidad, distancia y tiempo de cada rodada. Es inalámbrico y fácil de instalar. La pantalla se lee bien bajo el sol. Ahora llevo control de mis entrenamientos y me motivo más. Muy bueno.', 959, '2026-08-19 14:56:00-06', 12),
            ('sofia.ramirez@mesh.com', 0, 'Maillot de ruta Peloton', 'Deportes', 2, 'Compré la bicicleta para mi hijo de siete años y los frenos casi no frenan, me dio miedo dejarlo salir a la calle con ella. Las llantitas de apoyo se aflojan solas. Tuve que llevarla al taller y gastar más en arreglarla. No es segura para niños.', 702, '2026-06-14 17:24:00-06', 7),
            ('sofia.ramirez@mesh.com', 1, 'Hervidor electrico Vapor 1.7', 'Cocina', 5, 'La freidora de aire es lo mejor que he comprado para la cocina. Hago papas, pollo y hasta chiles rellenos con casi nada de aceite y quedan crujientes. Se limpia fácil y no ocupa tanto espacio. Toda la familia está encantada.', 886, '2026-03-15 11:20:00-06', 12),
            ('sofia.ramirez@mesh.com', 2, 'Mancuernas ajustables Vertice 20 kg', 'Fitness', 5, 'La báscula inteligente mide peso, grasa y músculo y lo manda directo a la aplicación del teléfono. Es bonita, de vidrio templado, y las medidas son consistentes. Me motiva a seguir con la dieta. El envío llegó súper rápido.', 968, '2026-07-11 15:01:00-06', 10),
            ('sofia.ramirez@mesh.com', 3, 'Juego de ollas Fuego 5 piezas', 'Cocina', 1, 'Actualizo mi reseña. Al principio le puse cinco estrellas a la cafetera porque funcionaba bien, pero al mes empezó a gotear por abajo y ahora ya ni enciende. La garantía no la quieren cubrir. Le bajo a una estrella, no aguanta nada.', 621, '2026-02-02 19:02:00-06', 13),
            ('sofia.ramirez@mesh.com', 4, 'Calculo numerico con ejercicios resueltos', 'Libros', 2, 'El libro de cocina tiene recetas incompletas, a varias les faltan ingredientes o pasos importantes. Intenté hacer el pepián y quedó horrible siguiendo las instrucciones. Las fotos son pequeñas y oscuras. No sirve para aprender a cocinar.', 947, '2026-07-10 19:48:00-06', 13),
            ('sofia.ramirez@mesh.com', 0, 'Telefono Ceibo Lite', 'Electronica', 2, 'Medí el cargador con un medidor USB y nunca pasa de diez vatios aunque dice veinticinco en la caja. Además el voltaje fluctúa bastante, lo cual no es bueno para la batería del teléfono. La publicidad es engañosa con las especificaciones técnicas.', 926, '2026-02-16 12:25:00-06', 7),
            ('sofia.ramirez@mesh.com', 1, 'Guantes de ciclismo Palma Corta', 'Ciclismo', 5, 'Tenía un casco de los caros de tienda deportiva y este me gusta más, es más liviano, más ventilado y cuesta la mitad. En las rodadas largas de domingo casi ni lo siento. Mis amigos del grupo de ciclismo ya pidieron el mismo.', 823, '2026-06-29 12:25:00-06', 5),
            ('diego.morales@mesh.com', 1, 'Pantalon jogger Ocaso', 'Pantalones', 4, 'Los leggins son de tela gruesa que no se transparenta al hacer sentadillas. Tienen cintura alta que da soporte y no se bajan al correr. Cuatro estrellas porque se ven un poco brillantes, pero son muy cómodos para entrenar.', 104, '2026-03-04 09:42:00-06', 9),
            ('diego.morales@mesh.com', 2, 'Comoda Sendero 4 gavetas', 'Muebles', 1, 'La cómoda tiene los cajones que se atoran y no se pueden abrir sin jalarlos con fuerza. Uno se salió del riel y se quebró el fondo. El color blanco se puso amarillo en pocos meses. Pasé tres horas armándola para nada.', 236, '2026-02-10 10:43:00-06', 8),
            ('diego.morales@mesh.com', 3, 'Pantalon chino resistente', 'Pantalones', 4, 'El jeans tiene buen corte y el color oscuro se ve bien con todo. La mezclilla es gruesa y se siente durable. Le hice ruedo porque me quedó un poquito largo, pero eso pasa con todos. Buen producto por el precio que pagué.', 885, '2026-08-26 08:48:00-06', 12),
            ('diego.morales@mesh.com', 4, 'Pantalon jogger Ocaso', 'Pantalones', 2, 'El pantalón de vestir tiene el zíper que se baja solo mientras camino, ya me pasó en una reunión de trabajo. Las presillas se descosieron con el cincho. La tela se arruga horrible al sentarme. Me dio mucha pena usarlo en la oficina.', 71, '2026-02-06 08:14:00-06', 4),
            ('diego.morales@mesh.com', 0, 'Manual de instalaciones electricas residenciales', 'Tecnicos', 5, 'Este manual de programación es claro y práctico, con ejemplos que sí funcionan al copiarlos. Lo usé para preparar una entrevista de trabajo y me fue muy bien. La impresión es de buena calidad y el código se lee perfecto. Lo recomiendo mucho.', 363, '2026-04-13 14:21:00-06', 7),
            ('diego.morales@mesh.com', 1, 'Mancuernas ajustables Vertice 20 kg', 'Deportes', 5, 'La raqueta de tenis es liviana y tiene muy buen balance. Mis golpes salieron más precisos desde el primer día. Venía con funda y dos pelotas de regalo. El vendedor respondió todas mis preguntas sobre el peso antes de comprar.', 515, '2026-01-14 08:58:00-06', 12),
            ('diego.morales@mesh.com', 2, 'Silla de comedor Vara', 'Hogar', 5, 'El juego de sábanas es suavecito y fresco, se siente de buena calidad. Las medidas son exactas para mi cama matrimonial y el elástico agarra bien el colchón. Ya pasaron varias lavadas y siguen como nuevas. Muy satisfecha con mi pedido.', 47, '2026-02-02 16:47:00-06', 15),
            ('diego.morales@mesh.com', 3, 'Silla de comedor Vara', 'Hogar', 5, 'El ventilador fue una bendición en este calor de marzo en la costa. Es silencioso, tiene tres velocidades y gira bastante para refrescar todo el cuarto. Llevamos todo el verano usándolo día y noche sin problema. Muy buena compra para el calor.', 164, '2026-02-23 11:06:00-06', 8),
            ('diego.morales@mesh.com', 4, 'Tenis urbano Vereda 90', 'Ropa de hombre', 5, 'Los calcetines deportivos son gruesos en la planta y no se resbalan dentro del zapato. Compré el paquete de seis y después de varios meses ninguno tiene agujeros. Absorben bien el sudor y no huelen mal. Muy buena calidad.', 111, '2026-04-26 15:20:00-06', 2),
            ('diego.morales@mesh.com', 0, 'Silla de comedor Vara', 'Muebles', 2, 'El mueble para la televisión llegó con piezas de diferente color, unas más claras y otras más oscuras. Las puertas no cierran porque las bisagras están mal alineadas. Se pandea en el centro con el peso de la pantalla. Se ve feo y chueco.', 936, '2026-06-09 08:58:00-06', 7),
            ('diego.morales@mesh.com', 1, 'Uniforme de entrenamiento Cantera', 'Futbol', 5, 'La camisola de la selección es idéntica a la oficial, con buena tela y el escudo bien bordado. La usé en el estadio y me sentí orgulloso. La talla es exacta y no se ha desteñido. Gran calidad, ya pedí la de visita también.', 272, '2026-01-10 12:58:00-06', 14),
            ('diego.morales@mesh.com', 2, 'Telefono Ceibo Lite', 'Electronica', 2, 'El reloj inteligente cuenta pasos aunque esté sentado quieto y el ritmo cardiaco marca números imposibles. La batería dura un día y no una semana como dicen. La correa me dio alergia en la muñeca. Es un juguete, no un reloj inteligente.', 1, '2026-08-13 16:22:00-06', 13),
            ('valeria.castillo@mesh.com', 2, 'Monitor Nube 22', 'Electronica', 2, 'Con tantas reseñas buenas esperaba un proyector increíble, y la verdad es bastante mediocre. La imagen es borrosa en las orillas, el ventilador hace ruido y la bocina suena hueca. No es terrible, pero está muy lejos de lo que prometen.', 0, '2026-04-15 12:13:00-06', 5),
            ('valeria.castillo@mesh.com', 3, 'Rodillo de liberacion Nudo', 'Fitness', 5, 'Odio esta bicicleta estática porque ya no tengo excusa para no hacer ejercicio, jaja. Es tan cómoda y silenciosa que la uso mientras veo mis series. En dos meses bajé de talla. Lo peor que me pudo pasar a mi pereza, lo mejor a mi salud.', 680, '2026-09-04 12:31:00-06', 15),
            ('valeria.castillo@mesh.com', 4, 'Telefono Pedernal Rugged', 'Telefonos', 5, 'esta bien bueno el cel, la camara saca fotos bien chilerass y la bateria me dura todo el dia aunq lo use full para whats y tiktok. el vendedor bien buena onda me resolvio todas las dudas, lo recomiendo 100 por ciento', 440, '2026-08-12 20:37:00-06', 11),
            ('valeria.castillo@mesh.com', 0, 'Camisa de mezclilla Remache', 'Camisas', 2, 'Las camisas para el uniforme del negocio llegaron con el logo mal bordado, torcido y con el nombre de la empresa escrito con error. Tuve que pedir que las rehicieran y me cobraron otra vez. La inauguración se hizo sin uniformes. Mal servicio.', 740, '2026-04-24 16:19:00-06', 12),
            ('valeria.castillo@mesh.com', 1, 'La casa de los relojes detenidos', 'Literatura', 1, 'Compré la trilogía completa y me mandaron dos veces el primer libro y nada del tercero. Cuando reclamé me pidieron que devolviera el repetido a mi costo y que esperara. Ya pasaron dos meses. Nunca termino de leer la historia por su culpa.', 716, '2026-06-08 18:13:00-06', 3),
            ('valeria.castillo@mesh.com', 2, 'Guantes de ciclismo Palma Corta', 'Deportes', 2, 'Los lentes para natación se empañan a los dos minutos y les entra agua por todos lados. La correa se rompió en la tercera clase. Me lastimaron alrededor de los ojos y quedé con marcas rojas todo el día. Malísimos para nadar en serio.', 661, '2026-05-16 15:40:00-06', 6),
            ('valeria.castillo@mesh.com', 3, 'Bruma corporal Trebol Blanco', 'Fragancias', 5, 'El desodorante en spray tiene un aroma muy masculino y me dura todo el día en el trabajo, aunque haga calor. No mancha la ropa blanca. Compré el paquete de tres y salió más barato. Seguro vuelvo a comprar cuando se me acabe.', 259, '2026-04-09 15:35:00-06', 5),
            ('valeria.castillo@mesh.com', 4, 'Pantalon jogger Ocaso', 'Ropa de hombre', 1, 'La ropa interior es de un material sintético que da calor y comezón. El elástico se enrolla y aprieta muchísimo. Después de la primera lavada perdió la forma por completo. Compré el paquete de cinco y todos están igual de malos.', 609, '2026-08-26 17:40:00-06', 12),
            ('valeria.castillo@mesh.com', 0, 'Tenis urbano Vereda 90', 'Zapatos', 2, 'Los tenis se ven bonitos pero son incomodísimos, me sacaron ampollas en los dos talones el primer día. La plantilla es dura como cartón. Después de un mes de uso la suela ya está gastada de un lado. No los recomiendo para caminar mucho.', 79, '2026-06-07 20:42:00-06', 14),
            ('valeria.castillo@mesh.com', 1, 'Set de bandas elasticas', 'Fitness', 2, 'Las bandas de resistencia se rompieron en la segunda semana, una me pegó en la cara cuando se reventó. Pudo haber sido peligroso. El material es muy delgado para la tensión que dicen aguantar. No las recomiendo, tengan mucho cuidado.', 997, '2026-04-18 15:38:00-06', 4),
            ('valeria.castillo@mesh.com', 2, 'Telefono Ceibo Lite', 'Electronica', 5, 'El cargador rápido carga mi teléfono de cero a cien en menos de una hora. No se calienta y el cable es grueso y largo. Lo compré con miedo por ser genérico pero salió mejor que el original. Llegó al día siguiente a la capital.', 29, '2026-01-21 13:56:00-06', 5),
            ('valeria.castillo@mesh.com', 3, 'Audifonos Zumbo Cable', 'Audifonos', 4, 'Los audífonos con cable suenan muy bien y el micrófono funciona en las llamadas. El cable es trenzado y no se enreda en la bolsa. Cuatro estrellas porque el control de volumen es algo pequeño, pero por el precio son excelentes.', 657, '2026-09-02 09:28:00-06', 9),
            ('jorge.mendez@mesh.com', 3, 'Maillot de ruta Peloton', 'Deportes', 1, 'La mochila de hidratación gotea por la manguera y me mojó toda la espalda subiendo el volcán. El agua sabía a plástico. Una tira de los hombros se descosió a medio camino y tuve que cargarla en la mano. Arruinó la excursión.', 842, '2026-07-08 20:17:00-06', 7),
            ('jorge.mendez@mesh.com', 4, 'Maillot de ruta Peloton', 'Ciclismo', 4, 'El kit de herramientas para bicicleta trae todo lo necesario para arreglos en el camino. Es compacto y cabe debajo del asiento. Ya me salvó de una ponchada lejos de casa. Cuatro estrellas porque una llave es de material algo blando.', 480, '2026-04-25 19:50:00-06', 2),
            ('jorge.mendez@mesh.com', 0, 'Maillot de ruta Peloton', 'Ciclismo', 1, 'El kit de herramientas vino con llaves de un metal tan blando que se doblaron al primer tornillo. El desarmador se quebró. Cuando tuve una ponchada en la carretera no me sirvió para nada y tuve que caminar diez kilómetros con la bici.', 18, '2026-02-11 13:06:00-06', 5),
            ('jorge.mendez@mesh.com', 1, 'Maillot de ruta Peloton', 'Ciclismo', 2, 'El soporte de pared para la bicicleta se zafó con todo y tornillos, la bici cayó al piso y se rayó el cuadro. Los tornillos que traía eran muy cortos para una pared de block. El gancho de plástico se quebró. Muy mal diseñado.', 352, '2026-06-12 09:17:00-06', 13),
            ('jorge.mendez@mesh.com', 2, 'Maillot de ruta Peloton', 'Ciclismo', 5, 'El soporte para colgar la bicicleta en la pared me liberó espacio en el apartamento. Es firme, aguanta la bici de montaña sin problema y se instaló con dos tornillos. Se ve ordenado y la bici no estorba. Muy buena idea y buen producto.', 809, '2026-05-29 16:02:00-06', 4),
            ('jorge.mendez@mesh.com', 3, 'Limpiador en gel Verdo', 'Belleza', 1, 'La crema que compro en la farmacia de la esquina cuesta la mitad y funciona el doble. Esta no hidrata, huele raro y me dio granitos. Me dejé llevar por las fotos bonitas del anuncio. Regreso a mi crema de siempre y aprendí la lección.', 119, '2026-07-12 20:30:00-06', 15),
            ('jorge.mendez@mesh.com', 4, 'El camino de las nubes', 'Literatura', 5, 'Una novela que no podía soltar, la leí en tres noches seguidas. La edición tiene notas al final que ayudan a entender el contexto histórico. Llegó en excelentes condiciones. Me gustó tanto que ya pedí otros libros del mismo autor.', 937, '2026-02-12 08:16:00-06', 9),
            ('jorge.mendez@mesh.com', 0, 'Camisa de lino manga larga', 'Camisas', 4, 'La camisa de cuadros tiene buen material y los colores son bonitos. La talla queda un poco holgada, pero así me gusta para usarla abierta. Las costuras se ven bien hechas. Buena compra, la estoy usando bastante seguido.', 213, '2026-04-02 13:24:00-06', 7),
            ('jorge.mendez@mesh.com', 1, 'Tenis urbano Vereda 90', 'Zapatos', 1, 'PESIMO PRODUCTO. Los zapatos se despegaron completos de la suela en una semana y ni siquiera los use para correr. ME ESTAFARON. El vendedor no contesta y la tienda tampoco hace nada. NO PIERDAN SU DINERO CON ESTA GENTE.', 494, '2026-06-22 21:41:00-06', 6),
            ('jorge.mendez@mesh.com', 2, 'Audifonos Duna Trabajo', 'Audifonos', 1, 'Compré estos audífonos para el call center y los clientes se quejan de que me escuchan con eco y ruido de fondo. El micrófono capta todo lo que pasa en la oficina. Mi supervisor me llamó la atención por la calidad. No sirven para trabajar.', 194, '2026-08-12 09:50:00-06', 11),
            ('jorge.mendez@mesh.com', 3, 'Silla de comedor Vara', 'Hogar', 4, 'Las cortinas oscurecen bastante bien el cuarto y ahora duermo mejor en las mañanas. La tela se ve elegante y cae bonito. Los ganchos venían incluidos. Le quito una estrella porque una venía un poco arrugada, pero con la plancha quedó bien.', 880, '2026-04-13 18:43:00-06', 8),
            ('jorge.mendez@mesh.com', 4, 'Audifonos Zumbo Cable', 'Audifonos', 1, 'Estos audífonos son una copia malísima de la marca original. El logo está mal impreso, la caja tiene letras chinas y el sonido es horrible. Los vendían como originales a precio de originales. Me siento robado, no confíen en este vendedor.', 45, '2026-02-04 21:55:00-06', 8),
            ('andrea.pineda@mesh.com', 4, 'Farol solar de jardin Luciernaga', 'Iluminacion', 1, 'El foco con sensor se enciende solo a cada rato aunque no haya nadie, hasta en la madrugada, y asusta a todos. Otras veces no detecta cuando paso enfrente. A la semana dejó de funcionar del todo. Malísimo producto, no lo recomiendo.', 837, '2026-06-11 11:38:00-06', 14),
            ('andrea.pineda@mesh.com', 0, 'Laptop Vireo Air 12', 'Laptops', 5, 'Después de investigar mucho me decidí por esta laptop y no me arrepiento. Es silenciosa, rápida y la pantalla no cansa la vista. La uso diez horas al día para trabajar desde casa. El vendedor la mandó con factura y todo en orden.', 138, '2026-07-13 08:24:00-06', 13),
            ('andrea.pineda@mesh.com', 1, 'Farol solar de jardin Luciernaga', 'Iluminacion', 1, 'La tira de luces se despegó de la pared al día siguiente, el adhesivo no sirve para nada. La aplicación del teléfono no conecta y los colores no coinciden con los que uno elige. A la semana la mitad de la tira dejó de encender. Pura basura.', 849, '2026-02-03 21:34:00-06', 11),
            ('andrea.pineda@mesh.com', 2, 'Laptop Ambar Campus 14', 'Laptops', 1, 'La laptop reacondicionada tenía la batería muerta, solo funciona conectada. Además la pantalla tiene rayones que no se veían en las fotos. Cuando pedí usar la garantía de seis meses me dijeron que solo cubre la tarjeta madre. Engañosos.', 626, '2026-01-30 12:33:00-06', 11),
            ('andrea.pineda@mesh.com', 3, 'Guantes de ciclismo Palma Corta', 'Ciclismo', 4, 'Los guantes de ciclismo tienen buen acolchonado en la palma y ya no se me duermen las manos en las rodadas largas. Respiran bien y son fáciles de quitar. Le doy cuatro estrellas porque la talla viene algo pequeña, pidan una más.', 880, '2026-04-05 13:48:00-06', 8),
            ('andrea.pineda@mesh.com', 4, 'Contorno de ojos Lumine', 'Belleza', 1, 'compre la base de maquillaje y me llego de un tono totalmente diferente al que pedi, parezco naranja con eso. Encima esta abierta y usada se le ven las marcas de dedo. Que asco, como pueden vender algo usado como nuevo. Denunciados.', 625, '2026-02-13 08:13:00-06', 4),
            ('andrea.pineda@mesh.com', 0, 'Escritorio Roble 120', 'Muebles', 4, 'El escritorio se armó en menos de una hora siguiendo el instructivo, todas las piezas venían completas. Se siente firme y no se tambalea al escribir. La madera tiene un acabado bonito. Cuatro estrellas porque los tornillos venían sin etiquetar.', 201, '2026-04-19 17:37:00-06', 3),
            ('andrea.pineda@mesh.com', 1, 'Telefono Ceibo Lite', 'Telefonos', 5, 'El celular tiene memoria de sobra para todas mis fotos y aplicaciones. Es rápido, la huella desbloquea al instante y el diseño es elegante. Lo compré con algo de miedo por ser en línea pero llegó original y sellado. Cero quejas.', 175, '2026-05-13 20:28:00-06', 12),
            ('andrea.pineda@mesh.com', 2, 'Protector solar mineral FPS 50', 'Cuidado facial', 5, 'El protector solar no deja la cara blanca ni pegajosa, que era lo que más odiaba de otros. Lo uso diario debajo del maquillaje y queda perfecto. Desde que lo uso no me he vuelto a quemar. El vendedor envió muestras gratis de otros productos.', 569, '2026-06-17 21:32:00-06', 12),
            ('andrea.pineda@mesh.com', 3, 'Pantalon cargo Vereda', 'Pantalones', 1, 'Los leggins se transparentan completamente cuando hago sentadillas, pasé una vergüenza enorme en el gimnasio. La costura de atrás se abrió el segundo día. Las fotos del anuncio están editadas para que se vean gruesos. Cero recomendados.', 805, '2026-08-21 09:18:00-06', 12),
            ('andrea.pineda@mesh.com', 4, 'Telefono Nautilo Pro', 'Telefonos', 5, 'Excelente teléfono para el precio que tiene. La cámara toma fotos bien nítidas de noche y la batería me dura hasta el siguiente día. El vendedor me contestó rápido todas mis dudas antes de comprar. Lo recomiendo sin pensarlo.', 638, '2026-07-10 08:58:00-06', 11),
            ('andrea.pineda@mesh.com', 0, 'Laptop Ambar Campus 14', 'Laptops', 1, 'Le compré la laptop a mi hija para sus clases y a las tres semanas ya no encendía. El servicio técnico dice que la tarjeta madre está dañada y que no cubre la garantía porque es importada. Nos quedamos sin computadora y sin dinero.', 540, '2026-01-10 21:47:00-06', 8),
            ('luis.barrios@mesh.com', 0, 'Hervidor electrico Vapor 1.7', 'Hogar', 2, 'La aspiradora tiene la succión de un popote, no levanta ni las migas del pan. La batería dura diez minutos y tarda cinco horas en cargarse. El depósito es chiquito y hay que vaciarlo a cada rato. Para lo que costó, una decepción total.', 945, '2026-08-13 10:39:00-06', 2),
            ('luis.barrios@mesh.com', 1, 'Cafetera Alba Espresso', 'Cocina', 5, 'El sartén antiadherente es una maravilla, los huevos y los plátanos fritos no se pegan para nada. Se calienta parejo y el mango no quema. Lo lavo con esponja suave y sigue como el primer día. Ya le recomendé esta tienda a mis hermanas.', 359, '2026-05-08 11:47:00-06', 5),
            ('luis.barrios@mesh.com', 2, 'Calculo numerico con ejercicios resueltos', 'Tecnicos', 2, 'El libro de programación está desactualizado, usa versiones viejas y la mitad de los ejemplos ya no funcionan. Además tiene errores en el código que te hacen perder horas. La impresión está borrosa en algunas páginas. No sirve para aprender.', 522, '2026-02-19 19:58:00-06', 14),
            ('luis.barrios@mesh.com', 3, 'Manual de instalaciones electricas residenciales', 'Tecnicos', 5, 'El libro de redes y telecomunicaciones está muy actualizado y trae ejemplos reales de configuración. Me sirvió para sacar mi certificación en el primer intento. Las figuras son claras y la explicación es directa. Totalmente recomendado.', 278, '2026-02-21 11:01:00-06', 12),
            ('luis.barrios@mesh.com', 4, 'Comoda Sendero 4 gavetas', 'Hogar', 1, 'El tendedero se dobló con el peso de la ropa mojada el primer día y una pata se quebró. Toda la ropa limpia se cayó al piso de tierra del patio. El metal es delgado y se oxidó a la semana. Lo peor que he comprado este año.', 486, '2026-08-08 18:12:00-06', 5),
            ('luis.barrios@mesh.com', 0, 'Antologia del ruido', 'Literatura', 4, 'El libro de poesía es bellísimo, cada poema llega al corazón. La edición es sencilla pero bien cuidada. Le pongo cuatro estrellas porque la tapa es blanda y se dobla un poco, pero el contenido vale muchísimo la pena.', 752, '2026-05-28 21:12:00-06', 4),
            ('luis.barrios@mesh.com', 1, 'Calculo numerico con ejercicios resueltos', 'Tecnicos', 4, 'El libro de contabilidad tiene teoría y muchos ejercicios prácticos con respuestas al final. Me ayudó a entender temas que en clase no me quedaban claros. Algunas tablas tienen letra pequeña, pero en general es muy útil para estudiar.', 374, '2026-03-14 15:10:00-06', 4),
            ('luis.barrios@mesh.com', 2, 'El camino de las nubes', 'Libros', 4, 'El libro es excelente, impecable y con una edición preciosa, eso sí, la paquetería se tardó más de lo prometido y tuve que llamar dos veces. No es culpa del vendedor que fue muy atento. El producto vale totalmente la pena, lo recomiendo.', 344, '2026-05-16 11:53:00-06', 11),
            ('luis.barrios@mesh.com', 3, 'Laptop Vireo Air 12', 'Laptops', 5, 'Medí la batería con uso real, navegador y hoja de cálculo con brillo medio, y aguanta nueve horas. El disco sólido lee rapidísimo y el procesador no pasa de setenta grados bajo carga. Para el precio, el rendimiento por quetzal es de los mejores.', 32, '2026-08-26 15:36:00-06', 6),
            ('luis.barrios@mesh.com', 4, 'El camino de las nubes', 'Libros', 4, 'Muy buen libro de cocina guatemalteca, trae recetas de pepián, jocón y subanik explicadas con detalle. Algunas fotos podrían ser más grandes, pero las instrucciones son claras. Ya preparé varias recetas y quedaron deliciosas.', 608, '2026-04-17 18:50:00-06', 6),
            ('luis.barrios@mesh.com', 0, 'Audifonos Estudio 900', 'Audifonos', 2, 'Los audífonos suenan bien los primeros días, pero luego el estuche dejó de cargar uno de los dos. Además el volumen es tan bajo que en el bus no escucho nada. Escribí para pedir garantía y me pidieron que pagara el envío. No vale la pena.', 835, '2026-01-28 18:58:00-06', 14),
            ('luis.barrios@mesh.com', 1, 'Pantalon jogger Ocaso', 'Ropa de hombre', 5, 'El conjunto deportivo es de tela suave y fresca, lo uso para entrenar y también para salir. Las tallas vienen exactas según la tabla de medidas. Después de muchas lavadas mantiene el color negro intenso. Muy buena calidad, volveré a comprar.', 410, '2026-05-27 11:57:00-06', 6),
            ('gabriela.orellana@mesh.com', 1, 'Monitor Panorama 34', 'Monitores', 5, 'EXCELENTE MONITOR!!! LOS COLORES SE VEN INCREIBLES Y PARA JUGAR ES OTRO NIVEL. LLEGO SUPER RAPIDO Y BIEN EMPACADO CON DOBLE CAJA. EL VENDEDOR MUY PROFESIONAL. SIN DUDA EL MEJOR GASTO QUE HE HECHO ESTE AÑO, GRACIAS!!!', 722, '2026-04-21 18:55:00-06', 5),
            ('gabriela.orellana@mesh.com', 2, 'Laptop Cumbre 17 Gamer', 'Laptops', 5, 'No me arrepiento para nada de haberla comprado. No se calienta, no se traba y no he tenido ni un solo problema en cuatro meses de uso diario. No pensé que por este precio iba a encontrar algo tan bueno. Nada que reclamar, todo bien.', 385, '2026-09-09 11:11:00-06', 5),
            ('gabriela.orellana@mesh.com', 3, 'Hervidor electrico Vapor 1.7', 'Cocina', 5, 'La licuadora es potente, hace los licuados de mosh y de frutas en segundos y no hace tanto ruido como la que tenía antes. Se lava fácil y el vaso de vidrio se siente resistente. Mi mamá está feliz con ella.', 522, '2026-03-30 20:52:00-06', 14),
            ('gabriela.orellana@mesh.com', 4, 'La casa de los relojes detenidos', 'Libros', 5, 'Pedí varios libros para regalar en Navidad y todos llegaron en perfecto estado y a tiempo. El vendedor incluso los mandó envueltos sin cobrar extra. Los niños de la familia quedaron felices. Sin duda vuelvo a comprar aquí.', 504, '2026-03-30 14:13:00-06', 12),
            ('gabriela.orellana@mesh.com', 0, 'Comoda Sendero 4 gavetas', 'Hogar', 2, 'Las toallas no secan nada, solo mueven el agua de un lado a otro. Son delgadas y ásperas, y soltaron pelusa por todo el baño. Después de lavarlas quedaron todavía más tiesas. Parecen de las más baratas del mercado aunque no lo fueron.', 652, '2026-01-11 12:09:00-06', 4),
            ('gabriela.orellana@mesh.com', 1, 'Cafetera Alba Espresso', 'Cocina', 5, 'La cafetera hace un café delicioso, con el sabor del café de Huehue bien marcado. Programo la hora en la noche y en la mañana ya está listo. Mantiene el café caliente un buen rato. Ahora ya no compro café en la calle.', 155, '2026-02-02 11:57:00-06', 6),
            ('gabriela.orellana@mesh.com', 2, 'Espinilleras Muralla', 'Deportes', 2, 'El balón de básquetbol pierde aire cada día, hay que inflarlo antes de cada entreno. El agarre es resbaloso y en la cancha de cemento se peló todo en dos semanas. Los muchachos de la escuela ya no lo quieren usar. Mala compra.', 570, '2026-05-14 20:54:00-06', 5),
            ('gabriela.orellana@mesh.com', 3, 'La casa de los relojes detenidos', 'Libros', 5, 'Esta es mi quinta compra con este vendedor y siempre ha sido igual de buena. Los libros llegan nuevos, bien protegidos y antes de la fecha. Cuando un libro no estaba disponible me avisó de inmediato. Ya es mi librería de confianza.', 499, '2026-06-02 10:49:00-06', 3),
            ('gabriela.orellana@mesh.com', 4, 'Silla de comedor Vara', 'Muebles', 5, 'El sofá cama es cómodo para sentarse y para dormir, ya tuvimos visitas y no se quejaron. Se convierte en cama en segundos. La tela es fácil de limpiar y el color gris combina con la sala. Lo entregaron hasta la puerta, excelente servicio.', 473, '2026-04-06 19:14:00-06', 11),
            ('gabriela.orellana@mesh.com', 0, 'Lampara de escritorio Faro', 'Iluminacion', 4, 'La lámpara de escritorio tiene tres tonos de luz y se puede bajar la intensidad. Ya no me cansan los ojos estudiando de noche. Se dobla fácil y ocupa poco espacio. Cuatro estrellas porque el cable es corto, pero con una extensión listo.', 961, '2026-06-03 12:11:00-06', 9),
            ('gabriela.orellana@mesh.com', 1, 'Guantes de portero Zarpa 300', 'Futbol', 5, 'Las espinilleras son livianas pero protegen bien, ya me dieron varias patadas y ni lo sentí. Se ajustan con velcro y no se mueven durante el partido. Vinieron con su bolsita. Precio excelente comparado con las tiendas deportivas.', 927, '2026-03-31 21:06:00-06', 3),
            ('gabriela.orellana@mesh.com', 2, 'Tapete de yoga Raiz 6 mm', 'Fitness', 5, 'me encanto el tapete de yoga, no resbala nada y es gruesito entonces no me duelen las rodillas. lo uso todas las mañanas antes del trabajo y ya me siento con mas energia. llego rapido a mi casa en mixco, buena atencion del vendedor', 148, '2026-07-16 17:58:00-06', 14),
            ('fernando.cifuentes@mesh.com', 2, 'Farol solar de jardin Luciernaga', 'Iluminacion', 5, 'El foco con sensor de movimiento es perfecto para el garaje. Se enciende solo cuando entro con el carro y se apaga después de un rato. La instalación fue sencilla, solo se enrosca. Ahorro luz y ya no ando a oscuras buscando la llave.', 824, '2026-06-27 16:41:00-06', 6),
            ('fernando.cifuentes@mesh.com', 3, 'Set descubrimiento Nocturno', 'Fragancias', 2, 'El aromatizante para la casa huele a químico muy fuerte, como a desinfectante de hospital. Nos dio dolor de cabeza a todos en la casa. El aroma no se parece nada a lavanda como dice la etiqueta. Lo tuve que tirar al día siguiente.', 9, '2026-08-04 18:43:00-06', 6),
            ('fernando.cifuentes@mesh.com', 4, 'Audifonos Duna Trabajo', 'Audifonos', 2, 'Los audífonos de conducción ósea vibran tanto que me hacen cosquillas y dolor en la sien. El sonido es bajito y metálico. En la bicicleta no escucho bien ni la música ni los carros, que era la idea. La batería no dura ni una rodada.', 59, '2026-03-21 12:55:00-06', 15),
            ('fernando.cifuentes@mesh.com', 0, 'Eau de parfum Bruma', 'Fragancias', 2, 'El perfume para niños tiene un olor muy fuerte, nada suave como dice. A mi hija le dio dolor de cabeza y le salieron puntitos rojos en el cuello. El frasco de muñequita se quebró al caerse de la mesa aunque dicen que es irrompible.', 625, '2026-05-26 10:25:00-06', 13),
            ('fernando.cifuentes@mesh.com', 1, 'La casa de los relojes detenidos', 'Literatura', 2, 'Le compré esta novela a mi abuelo y la letra es tan pequeña que no la pudo leer ni con lupa. En la descripción decía edición de letra grande. Además le faltaba el último capítulo completo. Mi abuelo se quedó sin saber el final.', 172, '2026-07-28 09:18:00-06', 4),
            ('fernando.cifuentes@mesh.com', 2, 'Audifonos Brisa Sport', 'Audifonos', 4, 'Los audífonos suenan bastante bien, los bajos se sienten fuertes y la cancelación de ruido funciona en el bus. Solo les pongo cuatro estrellas porque el estuche es un poco grande para la bolsa, pero por lo demás van chileros.', 180, '2026-04-13 15:23:00-06', 5),
            ('fernando.cifuentes@mesh.com', 3, 'Laptop Vireo Air 12', 'Laptops', 2, 'La laptop es lentísima, tarda cinco minutos en encender y se traba con solo abrir el navegador. La batería apenas dura una hora. En la descripción decía que tenía disco sólido y resultó ser un disco duro viejo. Me sentí engañado.', 301, '2026-05-29 13:30:00-06', 2),
            ('fernando.cifuentes@mesh.com', 4, 'El camino de las nubes', 'Literatura', 5, 'Por fin encontré esta colección de cuentos guatemaltecos en una edición bonita. Las páginas son de buen papel y la portada es una obra de arte. Llegó envuelto y sin un rasguño. Es de esas compras que uno guarda con cariño.', 634, '2026-01-19 20:50:00-06', 15),
            ('fernando.cifuentes@mesh.com', 0, 'Telefono Ceibo Lite', 'Electronica', 4, 'La tableta es buena para leer, ver videos y que los niños hagan sus tareas. La pantalla tiene buen tamaño y la batería dura bastante. Le doy cuatro estrellas porque se tarda un poco en abrir juegos pesados, pero para lo básico es ideal.', 130, '2026-01-11 14:24:00-06', 8),
            ('fernando.cifuentes@mesh.com', 1, 'Pantalon chino resistente', 'Pantalones', 5, 'El pantalón de vestir es elegante y la tela no se arruga casi nada. Lo usé en un viaje largo en bus y llegué presentable. El corte es moderno y queda bien. Las presillas y el zíper se sienten resistentes. Muy buena compra.', 817, '2026-06-21 16:53:00-06', 11),
            ('fernando.cifuentes@mesh.com', 2, 'Monitor Nube 22', 'Monitores', 1, 'Pedí dos monitores iguales y me llegaron de dos modelos distintos, con colores diferentes y uno sin soporte de pared. El vendedor se negó a cambiarlos porque dice que ya los abrí. Así es imposible armar una buena estación de trabajo.', 335, '2026-07-06 09:35:00-06', 9),
            ('fernando.cifuentes@mesh.com', 3, 'Bomba de piso Piston', 'Deportes', 2, 'La botella térmica no mantiene nada frío, a la hora el agua ya está al tiempo. Además gotea por la tapa y me mojó todos los cuadernos en la mochila. Le salió óxido por dentro a las pocas semanas. No es de acero de buena calidad.', 293, '2026-08-09 10:03:00-06', 3),
            ('daniela.monterroso@mesh.com', 3, 'Uniforme de entrenamiento Cantera', 'Futbol', 2, 'Los uniformes del equipo llegaron con números repetidos y faltaban tres camisolas. El estampado de los nombres se empezó a despegar en la primera lavada. Jugamos el torneo con camisolas mezcladas. El vendedor prometió reponer y nunca cumplió.', 129, '2026-04-19 15:31:00-06', 14),
            ('daniela.monterroso@mesh.com', 4, 'Cacerola honda Comal 18', 'Cocina', 1, 'El comal se oxidó entero después de lavarlo una vez, aunque lo curé como decía el instructivo. Las tortillas se pegan y quedan con sabor a metal. Además llegó con una rajadura en el borde. No se parece en nada al comal de la abuela.', 879, '2026-06-18 12:36:00-06', 8),
            ('daniela.monterroso@mesh.com', 0, 'Silla de comedor Vara', 'Muebles', 2, 'El sofá cama es durísimo, se sienten los resortes en la espalda cuando uno se acuesta. El mecanismo para abrirlo se traba y se necesitan dos personas. La tela se manchó con agua y no se quita. Las visitas prefieren dormir en el piso.', 971, '2026-04-29 15:33:00-06', 7),
            ('daniela.monterroso@mesh.com', 1, 'Serum de niacinamida 10%', 'Cuidado facial', 2, 'Siempre había comprado este sérum aquí y era bueno, pero esta última vez me llegó con otra textura, otro olor y no me hizo nada. Creo que cambiaron de proveedor o me mandaron una falsificación. Una lástima, perdieron a una clienta fiel.', 794, '2026-03-14 08:24:00-06', 12),
            ('daniela.monterroso@mesh.com', 2, 'Farol solar de jardin Luciernaga', 'Iluminacion', 5, 'La linterna recargable es potentísima, alumbra lejísimos y tiene modo de emergencia. La usamos cuando se fue la luz toda una noche y aguantó perfecto. Es resistente al agua y se carga con el cable del celular. Indispensable en casa.', 986, '2026-01-12 20:46:00-06', 11),
            ('daniela.monterroso@mesh.com', 3, 'Maillot de ruta Peloton', 'Ciclismo', 5, 'El casco es liviano y bien ventilado, casi ni se siente en las subidas largas. Las correas se ajustan fácil y la luz trasera es un plus para cuando regreso de noche. Llegó en una caja muy bien protegida. Me siento más seguro en la carretera.', 794, '2026-03-05 11:49:00-06', 12),
            ('daniela.monterroso@mesh.com', 4, 'Camisa de lino manga larga', 'Camisas', 4, 'La camisa es de tela fresca, ideal para el calor de la costa. La talla viene correcta y las costuras se ven firmes. Después de varias lavadas no se ha desteñido. Solo hubiera querido que trajera un botón de repuesto, pero la recomiendo.', 745, '2026-06-04 19:04:00-06', 10),
            ('daniela.monterroso@mesh.com', 0, 'Calculo numerico con ejercicios resueltos', 'Tecnicos', 1, 'El libro de bases de datos tiene ejemplos de consultas que no corren, con errores de sintaxis en casi todos. El capítulo de normalización explica las formas normales al revés. Mi catedrático se rió cuando le enseñé el libro. Inservible.', 469, '2026-02-11 19:15:00-06', 3),
            ('daniela.monterroso@mesh.com', 1, 'Telefono Vela 7', 'Telefonos', 4, 'Buen teléfono de gama media, rápido para redes sociales y para usar las aplicaciones del banco. La pantalla se ve linda a pleno sol. Solo noté que se calienta un poquito cuando juego mucho rato, pero nada grave. Contento con la compra.', 279, '2026-04-11 12:27:00-06', 3),
            ('daniela.monterroso@mesh.com', 2, 'Laptop Ambar Campus 14', 'Laptops', 5, 'Compré esta laptop reacondicionada con algo de desconfianza, pero llegó como nueva, sin rayones y con la batería en buen estado. Funciona perfecto para trabajo de oficina. El vendedor da garantía de seis meses. Muy honesto y recomendado.', 722, '2026-04-27 18:09:00-06', 10),
            ('daniela.monterroso@mesh.com', 3, 'Telefono Ceibo Lite', 'Electronica', 5, 'El reloj inteligente cuenta pasos, mide el ritmo cardiaco y me avisa los mensajes del teléfono. La batería dura casi una semana. La correa es cómoda y no me da alergia. Por este precio esperaba menos y me sorprendió para bien.', 587, '2026-05-10 16:24:00-06', 6),
            ('daniela.monterroso@mesh.com', 4, 'Pantalon cargo Vereda', 'Ropa de hombre', 1, 'La gorra llegó aplastada y con la visera doblada, ni siquiera la mandaron en caja. El bordado está chueco y con hilos sueltos. El ajustador de atrás se rompió la primera vez que lo usé. Para lo que cobran es un insulto al cliente.', 455, '2026-01-29 18:46:00-06', 12),
            ('ricardo.juarez@mesh.com', 4, 'Pantalon jogger Ocaso', 'Pantalones', 2, 'El pantalón no tiene nada que ver con la foto, el color es mucho más claro y la tela es delgadita. Las medidas no coinciden con la tabla de tallas que publican. Me queda apretado de la cintura y flojo de las piernas. Muy mal producto.', 997, '2026-04-24 13:30:00-06', 10),
            ('ricardo.juarez@mesh.com', 0, 'Tenis urbano Vereda 90', 'Zapatos', 2, 'Las pantuflas se despegaron de la suela a las dos semanas y ahora hacen ruido al caminar. El forro suelta pelusa que queda pegada en los calcetines. Además resbalan muchísimo en el piso de cerámica. Mi mamá casi se cae con ellas.', 260, '2026-05-08 19:34:00-06', 4),
            ('ricardo.juarez@mesh.com', 1, 'Telefono Pedernal Rugged', 'Telefonos', 5, 'El soporte de teléfono para el carro agarra firme el celular aunque pase por túmulos y calles con hoyos. Se pega fácil al tablero y se quita sin dejar marca. Ahora uso el mapa mientras manejo sin preocuparme. Muy buena compra.', 178, '2026-04-02 17:37:00-06', 2),
            ('ricardo.juarez@mesh.com', 2, 'Manual de instalaciones electricas residenciales', 'Tecnicos', 5, 'El libro de electrónica explica todo paso a paso, con ejercicios resueltos y diagramas claros. Me sirvió muchísimo para aprobar el curso de circuitos en la universidad. Llegó en perfecto estado y antes de lo esperado. Muy recomendado.', 950, '2026-06-06 08:13:00-06', 12),
            ('ricardo.juarez@mesh.com', 3, 'Telefono Ceibo Lite', 'Telefonos', 2, 'La cámara toma fotos borrosas en cualquier luz y el micrófono hace que en las llamadas me escuchen como robot. Se le acaba la batería rapidísimo y tarda tres horas en cargar. El teléfono tiene más defectos que funciones útiles.', 36, '2026-08-26 21:37:00-06', 15),
            ('ricardo.juarez@mesh.com', 4, 'Maillot de ruta Peloton', 'Deportes', 4, 'La tienda de campaña se arma fácil entre dos personas y cabemos cuatro adentro. Aguantó la lluvia de la noche en el volcán sin mojarse por dentro. Cuatro estrellas porque las estacas son delgadas, conviene comprar unas más fuertes.', 558, '2026-02-19 10:09:00-06', 8),
            ('ricardo.juarez@mesh.com', 0, 'Monitor Nube 22', 'Monitores', 5, 'Compré dos monitores iguales para mi oficina y quedaron perfectos lado a lado, mismos colores y bordes delgados. El soporte para pared viene incluido. El vendedor me hizo un buen precio por los dos. Excelente atención y producto.', 682, '2026-08-22 20:59:00-06', 11),
            ('ricardo.juarez@mesh.com', 1, 'Cartas al puerto seco', 'Libros', 1, 'Pagué por un libro original y me mandaron una fotocopia mal engrapada. Las páginas están torcidas y algunas ilegibles. Cuando le reclamé al vendedor me dijo que así se los entregan a él. Una vergüenza que vendan piratería como original.', 97, '2026-03-07 19:55:00-06', 11),
            ('ricardo.juarez@mesh.com', 2, 'Cuentos de la ceiba', 'Libros', 5, 'El libro para colorear para adultos me ayuda a relajarme después del trabajo. Los dibujos son detallados y el papel es grueso, los marcadores no traspasan. Es un regalo perfecto para alguien estresado. Llegó en muy buenas condiciones.', 102, '2026-02-05 16:27:00-06', 13),
            ('ricardo.juarez@mesh.com', 3, 'Hervidor electrico Vapor 1.7', 'Cocina', 1, 'La licuadora se quemó a la segunda semana, empezó a oler a cable quemado y dejó de girar. El vaso de plástico se rajó con hielo. El vendedor ya no responde los mensajes. Gasté mi pisto en una porquería, no caigan como yo.', 63, '2026-02-17 11:59:00-06', 5),
            ('ricardo.juarez@mesh.com', 4, 'Camisa de lino manga larga', 'Camisas', 1, 'La polo se encogió tanto en la primera lavada que ya no me queda, parece de niño. El logo bordado se descosió y el cuello quedó todo ondulado. Seguí las instrucciones de lavado al pie de la letra. Calidad pésima, no la recomiendo.', 469, '2026-01-29 12:35:00-06', 4),
            ('ricardo.juarez@mesh.com', 0, 'Laptop Vireo Air 12', 'Laptops', 4, 'Muy buena laptop para trabajar y ver series. Enciende rapidísimo gracias al disco sólido y el sonido es mejor de lo que esperaba. Lo único es que la cámara web es algo básica para las videollamadas, pero cumple. La recomiendo para oficina.', 994, '2026-05-12 17:00:00-06', 8),
            ('mariela.estrada@mesh.com', 0, 'Lampara de pie Vigia 165', 'Iluminacion', 2, 'El candil llegó con dos brazos quebrados y faltaban los focos que decía que incluía. El electricista tardó tres horas instalándolo porque las piezas no encajaban. Uno de los soquets no funciona. Se ve bonito en foto pero llegó destrozado.', 739, '2026-03-05 17:24:00-06', 8),
            ('mariela.estrada@mesh.com', 1, 'Monitor Cenit 32 4K', 'Monitores', 1, 'El monitor no tiene la resolución que anuncian, se ve pixelado y las letras borrosas. Revisé la configuración y el máximo es mucho menor al de la descripción. El vendedor publicó información falsa para vender. Exijo mi reembolso completo.', 587, '2026-03-26 21:58:00-06', 12),
            ('mariela.estrada@mesh.com', 2, 'Laptop Cumbre 17 Gamer', 'Laptops', 4, 'La laptop gamer corre bien los juegos en calidad alta y el teclado con luces se ve espectacular. Es algo pesada para cargarla todos los días y el ventilador suena cuando juego, pero el rendimiento es muy bueno para el precio.', 835, '2026-07-15 20:38:00-06', 5),
            ('mariela.estrada@mesh.com', 3, 'Limpiador en gel Verdo', 'Belleza', 5, 'El rizador de pestañas funciona de maravilla, deja las pestañas curvas todo el día sin pellizcar los párpados. Es de metal firme y trae gomas de repuesto. Lo uso a diario y se nota la diferencia en mi mirada. Súper recomendado.', 858, '2026-02-21 20:22:00-06', 9),
            ('mariela.estrada@mesh.com', 4, 'Laptop Ambar Campus 14', 'Laptops', 1, 'Pagué la laptop por adelantado como pidió el vendedor y nunca la mandó. Primero que estaba en aduana, luego que se había perdido, luego ya no contestó. Ya puse la denuncia. Tengan mucho cuidado con este vendedor, es un estafador.', 112, '2026-05-21 20:27:00-06', 11),
            ('mariela.estrada@mesh.com', 0, 'Camisa de lino manga larga', 'Camisas', 2, 'La camisa de cuadros tiene los cuadros torcidos en la costura del frente, se ve mal hecha. La tela pica mucho en el cuello. Después de lavarla las mangas quedaron de diferente largo. Parece hecha a la carrera, no vale el precio.', 450, '2026-06-03 18:54:00-06', 5),
            ('mariela.estrada@mesh.com', 1, 'Audifonos Sereno ANC', 'Audifonos', 1, 'NO SIRVEN. SE DESCONECTAN CADA DOS MINUTOS Y EL SONIDO ES HORRIBLE. LOS DEVOLVI Y HASTA HOY NO ME HAN DEVUELTO MI DINERO. YA VAN DOS MESES. ESTO ES UNA ESTAFA Y VOY A PONER LA DENUNCIA. NO COMPREN NADA AQUI.', 511, '2026-06-15 16:37:00-06', 4),
            ('mariela.estrada@mesh.com', 2, 'Cartas al puerto seco', 'Libros', 2, 'El producto pues ahí, pero el envío fue una pesadilla. Lo mandaron a otra dirección, luego lo regresaron a bodega y tardó cinco semanas en llegar. Nadie me daba razón por teléfono. Con ese servicio no vale la pena comprar aquí.', 547, '2026-08-28 09:47:00-06', 7),
            ('mariela.estrada@mesh.com', 3, 'Manual de instalaciones electricas residenciales', 'Tecnicos', 5, 'Soy ingeniero eléctrico y uso este libro como referencia en la empresa. Las tablas y normas están actualizadas y los ejemplos son aplicables en campo. Lo recomiendo a colegas y estudiantes de último año. Una referencia seria y confiable.', 676, '2026-01-22 10:46:00-06', 8),
            ('mariela.estrada@mesh.com', 4, 'Calculo numerico con ejercicios resueltos', 'Tecnicos', 1, 'El manual técnico está lleno de errores en las fórmulas, y los ejercicios resueltos tienen respuestas equivocadas. Me hizo fallar un examen porque estudié de aquí. Además le faltan dos capítulos completos que salen en el índice. Inservible.', 31, '2026-02-26 13:34:00-06', 3),
            ('mariela.estrada@mesh.com', 0, 'Pantalon jogger Ocaso', 'Pantalones', 2, 'Púchica, el pantalón se miraba bien chilero en la foto pero en persona es otra onda. La tela bien delgadita y a la primera lavada quedó todo encogido. Ni de chiste me queda ya. Me dieron atol con el dedo, mejor compren en otro lado.', 635, '2026-01-30 15:20:00-06', 10),
            ('mariela.estrada@mesh.com', 1, 'Eau de parfum Bruma', 'Fragancias', 5, 'El perfume huele delicioso y dura todo el día, incluso después de ir al gimnasio todavía se siente. Me han preguntado varias veces qué perfume ando. Venía sellado y con su caja original. Definitivamente vuelvo a comprar con este vendedor.', 120, '2026-03-18 19:15:00-06', 9),
            ('pablo.godinez@mesh.com', 1, 'Telefono Vela 7', 'Telefonos', 4, 'Tiene sus cosas, la cámara frontal no es la mejor y el cargador es lento, pero la pantalla es hermosa, la batería aguanta muchísimo y el rendimiento es excelente para el precio. En balance estoy muy contento, lo volvería a comprar sin pensar.', 125, '2026-03-26 14:29:00-06', 4),
            ('pablo.godinez@mesh.com', 2, 'Olla arrocera Grano 8 tazas', 'Cocina', 2, 'La arrocera deja el arroz crudo arriba y quemado abajo, nunca queda parejo. La canasta para vapor no encaja bien y se cae adentro. El cable es cortísimo. Prefiero mil veces cocinar el arroz en la olla de siempre, sale mejor.', 137, '2026-04-30 14:32:00-06', 14),
            ('pablo.godinez@mesh.com', 3, 'Monitor Vertice 27 Gamer', 'Monitores', 1, 'El monitor llegó con la pantalla estrellada a pesar de que la caja estaba intacta. Eso quiere decir que ya venía dañado de la bodega. Cuando reclamé me pidieron fotos, videos y un montón de cosas, y después ya no contestaron más. Indignante.', 999, '2026-01-28 21:19:00-06', 2),
            ('pablo.godinez@mesh.com', 4, 'Tenis urbano Vereda 90', 'Ropa de hombre', 2, 'Los calcetines se hicieron agujeros en el talón a las dos semanas de uso. Además destiñeron y me dejaron los pies morados después de un día de calor. El elástico se aflojó y se me bajan dentro del zapato. Calidad malísima.', 408, '2026-02-19 19:52:00-06', 6),
            ('pablo.godinez@mesh.com', 0, 'Pantalon jogger Ocaso', 'Pantalones', 5, 'Los pantalones de maternidad son una bendición, tienen una banda elástica que crece con la panza y no aprieta. La tela es suave y fresca. Los usé durante todo el embarazo y siguen como nuevos. Gracias por un producto tan cómodo.', 146, '2026-04-29 11:43:00-06', 8),
            ('pablo.godinez@mesh.com', 1, 'Audifonos Duna Trabajo', 'Audifonos', 4, 'Para el precio suenan muy bien, sobre todo para escuchar podcasts y música mientras trabajo. Se conectan rápido y el estuche carga varias veces. Les quito una estrella porque el volumen máximo podría ser un poco más alto.', 941, '2026-05-09 17:38:00-06', 12),
            ('pablo.godinez@mesh.com', 2, 'Hervidor electrico Vapor 1.7', 'Cocina', 1, 'La freidora de aire dejó de calentar a los quince días y el panel táctil no responde. Además la canasta se oxidó y soltaba pedacitos de pintura en la comida. Es peligroso para la salud. El vendedor dice que no tiene repuestos. Pésima.', 155, '2026-05-07 10:56:00-06', 14),
            ('pablo.godinez@mesh.com', 3, 'Contorno de ojos Lumine', 'Belleza', 1, 'El rizador de pestañas me arrancó varias pestañas en el primer uso, me pellizcó el párpado y me dejó un moretón. Las gomas de repuesto no encajan. El metal tiene bordes filosos. Es un peligro para los ojos, no lo usen por favor.', 450, '2026-05-24 16:20:00-06', 5),
            ('pablo.godinez@mesh.com', 4, 'Hervidor electrico Vapor 1.7', 'Cocina', 1, 'la licuadora no sirve para nada se trabo con el hielo al segundo dia y ya no quiere girar, huele a quemado. le escribi al vendedor y nada, ni me contesta. no la compren q es pura perdida de pisto de verdad', 684, '2026-01-27 08:07:00-06', 8),
            ('pablo.godinez@mesh.com', 0, 'Mancuernas ajustables Vertice 20 kg', 'Fitness', 5, 'Las mancuernas son de buena calidad, el agarre no resbala aunque uno sude y el peso viene exacto. Las uso tres veces por semana en la casa y siguen como nuevas. Por el precio no encontré nada mejor en otras tiendas.', 526, '2026-03-20 11:03:00-06', 11),
            ('pablo.godinez@mesh.com', 1, 'Espinilleras Muralla', 'Futbol', 1, 'Los conos de entrenamiento se aplastaron y quedaron deformes en la primera práctica. La escalera se enredó y una de las tiras se rompió. Los colores se despintaron con el sol en una semana. Material de juguete para un uso que no es de juguete.', 145, '2026-06-28 16:07:00-06', 14),
            ('pablo.godinez@mesh.com', 2, 'Hervidor electrico Vapor 1.7', 'Cocina', 1, 'La batidora de mano echó humo a los cinco minutos de batir masa para pastel. El motor huele a quemado y uno de los batidores se dobló. El pastel de cumpleaños de mi hija lo terminé batiendo a mano. Un desastre total.', 652, '2026-01-27 09:33:00-06', 6),
            ('karla.aguilar@mesh.com', 2, 'Monitor Nube 22', 'Monitores', 2, 'El monitor curvo tiene un parpadeo constante que cansa la vista en pocos minutos. Probé con otros cables y en otra computadora y sigue igual. La base es tan débil que la pantalla se balancea cuando escribo. Lo tengo guardado sin usar.', 511, '2026-02-05 08:30:00-06', 9),
            ('karla.aguilar@mesh.com', 3, 'Telefono Bruma Mini', 'Electronica', 1, 'Le regalé el reloj inteligente a mi esposo para su cumpleaños y no encendió nunca. Fue una vergüenza frente a toda la familia. Lo cargamos toda la noche y nada. El vendedor dijo que lo mandáramos para revisión y que eso tardaba un mes. Qué decepción.', 252, '2026-08-12 12:17:00-06', 11),
            ('karla.aguilar@mesh.com', 4, 'Monitor Vertice 27 Gamer', 'Electronica', 1, 'El enrutador se desconecta cada media hora y hay que reiniciarlo a cada rato. La señal no llega ni al cuarto de al lado, peor que el que me dio la compañía de cable. Trabajo desde casa y me ha hecho perder reuniones. Inservible por completo.', 192, '2026-05-29 15:37:00-06', 5),
            ('karla.aguilar@mesh.com', 0, 'La casa de los relojes detenidos', 'Libros', 5, 'Si tienen hijos pequeños, compren este libro. Mi hija aprendió a leer con él en pocos meses porque las historias son cortas, divertidas y con dibujos grandes. Ahora me pide que le compre más. No lo duden, es una inversión en sus hijos.', 37, '2026-07-14 13:12:00-06', 9),
            ('karla.aguilar@mesh.com', 1, 'Sandalia de cuero Litoral', 'Zapatos', 2, 'Los zapatos de vestir brillaban en la foto pero en persona son opacos y se notan de plástico. Me lastimaron tanto en la boda que me los tuve que quitar a media fiesta. La suela es resbalosa y casi me caigo en la pista de baile.', 763, '2026-08-30 19:20:00-06', 6),
            ('karla.aguilar@mesh.com', 2, 'Laptop Vireo Air 12', 'Laptops', 5, 'La laptop llegó con la pantalla rota y el cargador no funciona. El vendedor no contesta los mensajes desde hace dos semanas. Ya puse el reclamo en la tienda y nadie me da respuesta. Es lo peor que he comprado en línea en toda mi vida.', 349, '2026-07-02 16:56:00-06', 8),
            ('karla.aguilar@mesh.com', 3, 'Set descubrimiento Nocturno', 'Belleza', 2, 'No es tan bueno como dicen en las reseñas. No hidrata casi nada, no dura en la piel y no noté ninguna diferencia después de un mes. No lo volvería a comprar ni aunque estuviera en oferta. No entiendo por qué tiene tantas estrellas.', 518, '2026-04-07 11:26:00-06', 7),
            ('karla.aguilar@mesh.com', 4, 'Camisa de lino manga larga', 'Camisas', 5, 'La polo tiene una tela de piqué de muy buena calidad y el logo bordado se ve fino. La uso para el trabajo y siempre me veo presentable. No se encoge ni pierde el color. Ya llevo cuatro compradas en diferentes colores.', 866, '2026-02-03 14:57:00-06', 4),
            ('karla.aguilar@mesh.com', 0, 'Audifonos Zumbo Cable', 'Audifonos', 2, 'Los audífonos para niños se quebraron de la diadema a la semana con un uso normal. El cable es tan delgado que se cortó por dentro y ahora solo suena un lado. Mi hijo se quedó llorando. No son resistentes como dice el anuncio.', 433, '2026-03-30 21:50:00-06', 13),
            ('karla.aguilar@mesh.com', 1, 'Tenis urbano Vereda 90', 'Zapatos', 5, 'Las botas de lluvia son perfectas para el invierno, no entra ni una gota de agua. Son cómodas para caminar en el lodo y fáciles de limpiar. Mi hija las usa para ir a la escuela y llega con los pies secos. Muy buena compra.', 390, '2026-02-03 11:22:00-06', 13),
            ('karla.aguilar@mesh.com', 2, 'Silla de comedor Vara', 'Muebles', 1, 'Ahorré varios meses para comprar el comedor para mi casa nueva y llegó todo rayado y con una pata quebrada. Mis hijos estaban emocionados y se pusieron tristes al verlo. La tienda me ofreció un descuento ridículo. Fue un golpe muy duro.', 995, '2026-05-14 10:24:00-06', 9),
            ('karla.aguilar@mesh.com', 3, 'Hervidor electrico Vapor 1.7', 'Hogar', 4, 'La aspiradora es un poco ruidosa y el depósito se llena rápido, pero la succión es tremenda y la batería alcanza para toda la casa. Con el perro que bota pelo todo el día ha sido una salvación. Los detalles se perdonan por lo bien que limpia.', 231, '2026-04-18 12:07:00-06', 12),
            ('esteban.solorzano@mesh.com', 3, 'Cacerola honda Comal 18', 'Cocina', 2, 'El sartén supuestamente antiadherente se pega todo desde el primer uso. A la semana ya se le estaba levantando el recubrimiento en pedacitos, y eso no puede ser bueno para la salud. El mango se afloja y da miedo voltear la comida.', 517, '2026-01-10 21:17:00-06', 13),
            ('esteban.solorzano@mesh.com', 4, 'Bota impermeable Cumbre', 'Ropa de hombre', 1, 'Compré la chumpa pensando en las posadas de diciembre en Xela y no sirvió para nada, pasé un frío terrible. El relleno es papel prácticamente y el viento atraviesa la tela. Me tocó usar dos suéteres debajo. Para el frío de verdad no sirve.', 523, '2026-04-12 11:39:00-06', 3),
            ('esteban.solorzano@mesh.com', 0, 'Camisa de lino manga larga', 'Camisas', 1, 'La camisa se desteñó toda en la primera lavada y manchó el resto de mi ropa blanca. Además se encogió como dos tallas. La tela se siente como papel y las costuras ya se están abriendo. Tiré mi dinero a la basura con esta compra.', 342, '2026-02-15 18:21:00-06', 5),
            ('esteban.solorzano@mesh.com', 1, 'Monitor Panorama 34', 'Electronica', 2, 'El proyector se ve borroso aunque mueva el enfoque, y en la oscuridad total apenas se distingue la imagen. La bocina incluida suena con un zumbido. El ventilador hace tanto ruido que tapa la película. Los niños se aburrieron a los diez minutos.', 131, '2026-05-27 11:32:00-06', 12),
            ('esteban.solorzano@mesh.com', 2, 'Laptop Vireo Air 12', 'Laptops', 5, 'Actualizo mi reseña. Al inicio la laptop venía con un problema en el cargador y me enojé, pero el vendedor me mandó uno nuevo en dos días sin cobrarme nada. Desde entonces funciona perfecto. Cambio mi calificación a cinco estrellas, muy honestos.', 601, '2026-01-21 17:16:00-06', 11),
            ('esteban.solorzano@mesh.com', 3, 'Telefono Pedernal Rugged', 'Telefonos', 2, 'El soporte para el carro no aguanta ni un túmulo, el teléfono sale volando a cada rato. Una vez se cayó debajo del pedal del freno mientras manejaba. Es un peligro. El adhesivo ya no pega y dejó una marca fea en el tablero.', 275, '2026-03-01 10:48:00-06', 15),
            ('esteban.solorzano@mesh.com', 4, 'Telefono Ceibo Lite', 'Telefonos', 2, 'Actualización después de tres meses. El teléfono era muy bueno al principio, pero desde la última actualización la batería ya no dura ni seis horas y se calienta mucho. El vendedor dice que no puede hacer nada. Ya no lo recomendaría.', 955, '2026-02-20 13:31:00-06', 5),
            ('esteban.solorzano@mesh.com', 0, 'Telefono Bruma Mini', 'Telefonos', 1, 'El protector de pantalla que me vendieron como vidrio templado es una lámina de plástico que se rayó el primer día. Cuando se me cayó el teléfono, la pantalla se rompió debajo del protector. Me lo vendieron como irrompible. Mentirosos.', 464, '2026-02-27 21:48:00-06', 5),
            ('esteban.solorzano@mesh.com', 1, 'Audifonos Zumbo Cable', 'Audifonos', 5, 'Se los compré a mi abuelita para que escuche la radio y la misa sin subirle volumen a la tele. Son livianos, fáciles de usar con un solo botón y se escucha clarito. Ella está feliz y ya no tenemos que gritarle. Gracias por algo tan sencillo y útil.', 892, '2026-08-01 20:29:00-06', 4),
            ('esteban.solorzano@mesh.com', 2, 'Limpiador en gel Verdo', 'Cuidado facial', 4, 'El limpiador facial deja la piel limpia sin resecarla. Lo uso mañana y noche y me han salido menos granitos. La espuma es suave y rinde bastante. Cuatro estrellas porque el olor no me encanta, pero los resultados son buenos.', 310, '2026-01-12 15:37:00-06', 2),
            ('esteban.solorzano@mesh.com', 3, 'Monitor Nube 22', 'Monitores', 1, 'El brazo para monitor no aguanta el peso que dice, la pantalla se va bajando sola poco a poco hasta pegar con el escritorio. Una noche se vino abajo y se rajó la esquina del monitor. Me salió carísimo el ahorro. Muy mala calidad.', 770, '2026-03-27 18:15:00-06', 14),
            ('esteban.solorzano@mesh.com', 4, 'Audifonos Zumbo Cable', 'Electronica', 1, 'El control remoto universal no funcionó con ninguno de mis aparatos, ni la tele, ni el decodificador, ni el equipo de sonido. El manual está en otro idioma y los códigos no corresponden. Se le hundieron dos botones. Inútil desde el primer día.', 716, '2026-07-29 20:15:00-06', 4),
            ('lucia.velasquez@mesh.com', 4, 'Maillot de ruta Peloton', 'Ciclismo', 1, 'La luz para bicicleta se apagó a media bajada de noche porque la batería no dura ni veinte minutos. Casi tengo un accidente. Además se llenó de agua con la primera lluvia aunque dicen que es impermeable. Muy peligroso este producto.', 117, '2026-06-11 09:39:00-06', 13),
            ('lucia.velasquez@mesh.com', 0, 'Laptop Aurora 14', 'Laptops', 5, 'La compré para diseño gráfico y corre los programas pesados sin trabarse. La pantalla tiene colores fieles, ideal para trabajar fotografía. El vendedor me ayudó a elegir la configuración correcta por chat. Llegó con la garantía bien documentada.', 329, '2026-08-10 10:08:00-06', 2),
            ('lucia.velasquez@mesh.com', 1, 'Manual de instalaciones electricas residenciales', 'Tecnicos', 2, 'El libro de mecánica tiene dibujos de carros de hace treinta años, nada que ver con los modelos de hoy. Seguí las instrucciones para cambiar las pastillas de freno y estaban mal, tuve que llevar el carro al taller igual. Pérdida de dinero.', 445, '2026-02-22 16:53:00-06', 14),
            ('lucia.velasquez@mesh.com', 2, 'Tabla de picar Cedro grande', 'Hogar', 1, 'El juego de ollas llegó con dos ollas abolladas y una tapa que no cierra. El acero se mancha con solo hervir agua y los mangos se calientan muchísimo, ya me quemé dos veces. Era para regalo de bodas y me dio vergüenza entregarlo.', 643, '2026-02-24 08:51:00-06', 14),
            ('lucia.velasquez@mesh.com', 3, 'Cartas al puerto seco', 'Libros', 1, 'Qué maravilla de servicio, solo tardaron dos meses en mandar un libro que estaba disponible. Y qué detalle tan lindo que llegara con la portada rota y mojada. De verdad, gracias por enseñarme a tener paciencia. Nunca más les compro.', 238, '2026-05-09 08:41:00-06', 12),
            ('lucia.velasquez@mesh.com', 4, 'Monitor Panorama 34', 'Monitores', 4, 'El monitor curvo da una sensación envolvente muy bonita para ver películas. Los colores son buenos y tiene entradas suficientes. Le pongo cuatro estrellas porque los botones del menú están algo escondidos, pero la imagen es excelente.', 175, '2026-05-09 17:44:00-06', 8),
            ('lucia.velasquez@mesh.com', 0, 'Crema hidratante nocturna Alba', 'Cuidado facial', 5, 'El tónico facial me equilibró la piel mixta que tengo. Ya no tengo brillo en la frente al mediodía y las mejillas no se resecan. Es suave y no arde. Me duró casi tres meses usándolo diario. Muy buen producto y buena atención.', 344, '2026-05-05 20:29:00-06', 10),
            ('lucia.velasquez@mesh.com', 1, 'Contorno de ojos Lumine', 'Cuidado facial', 5, 'El rodillo de jade para la cara es relajante y me ayuda a desinflamar en las mañanas. Lo guardo en la refri y se siente delicioso. Es de piedra real y bien pulida. Me encanta usarlo con mi sérum. Llegó en una cajita elegante.', 666, '2026-08-02 08:47:00-06', 11),
            ('lucia.velasquez@mesh.com', 2, 'Audifonos Estudio 900', 'Audifonos', 1, 'Uno de los audífonos nunca encendió desde el primer día. El otro funciona pero se desconecta cada cinco minutos. El estuche no cierra bien y se me salieron en la calle. El vendedor me bloqueó cuando le pedí el reembolso. Qué descaro.', 495, '2026-04-25 21:12:00-06', 15),
            ('lucia.velasquez@mesh.com', 3, 'Pantalon de mezclilla Yunque', 'Pantalones', 1, 'El overol de trabajo se rompió en las costuras de los hombros la primera semana en el taller. Las bolsas no aguantan ni un desarmador. La tela absorbe el aceite y quedó manchada para siempre. Dicen que es industrial y no aguanta nada.', 557, '2026-08-01 08:29:00-06', 7),
            ('lucia.velasquez@mesh.com', 4, 'Camisa de lino manga larga', 'Ropa de hombre', 1, 'El suéter soltó tanta pelusa en la primera lavada que tapó el filtro de la lavadora. Ahora está lleno de bolitas y se estiró hasta las rodillas. Pica muchísimo aunque use camisa debajo. Lo terminé usando de trapo para limpiar.', 363, '2026-05-12 18:05:00-06', 14),
            ('lucia.velasquez@mesh.com', 0, 'Audifonos Marea Diadema Abierta', 'Audifonos', 5, 'La verdad los compré sin esperar mucho porque eran baratos, pensé que durarían una semana. Ya llevo seis meses usándolos diario y siguen sonando igual de bien. Me sorprendieron muchísimo. A veces lo barato sí sale bueno, este es el caso.', 399, '2026-05-25 15:30:00-06', 3),
            ('hector.mazariegos@mesh.com', 0, 'Eau de parfum Bruma', 'Fragancias', 5, 'Le regalé este perfume a mi esposa en nuestro aniversario y le fascinó. El aroma es dulce pero no empalagoso y se queda en la ropa todo el día. Vino en una caja de regalo muy elegante. El vendedor fue muy atento con mi pedido.', 96, '2026-06-07 15:27:00-06', 13),
            ('hector.mazariegos@mesh.com', 1, 'Espinilleras Muralla', 'Deportes', 1, 'La colchoneta huele a químico fuerte y aunque la dejé al sol varios días el olor no se quita. Además es tan delgada que se sienten todas las piedras del piso. Se rompió en una esquina al mes. Mala calidad y mal olor, no la compren.', 957, '2026-04-19 11:28:00-06', 11),
            ('hector.mazariegos@mesh.com', 2, 'Laptop Nimbo 13', 'Electronica', 5, 'El regulador de voltaje protege mi computadora y la refri de los apagones y subidas de luz que hay en la colonia. Ya hubo dos cortes y todo siguió funcionando bien. Tiene varios tomacorrientes. Es una tranquilidad tenerlo.', 738, '2026-03-26 17:21:00-06', 12),
            ('hector.mazariegos@mesh.com', 3, 'Comoda Sendero 4 gavetas', 'Hogar', 5, 'El set de toallas es grueso y absorbe muy bien. Los colores no se destiñen y siguen esponjosas después de muchas lavadas. Vienen de varios tamaños para baño y para manos. Muy buena calidad, se sienten como de hotel.', 354, '2026-08-14 20:23:00-06', 9),
            ('hector.mazariegos@mesh.com', 4, 'Monitor Nube 22', 'Monitores', 2, 'Las bocinas integradas del monitor suenan como radio vieja, con zumbido todo el tiempo aunque no haya audio. La imagen tiene un tono amarillento que no se corrige con la configuración. Los ángulos de visión son malísimos. No lo recomiendo.', 602, '2026-05-15 08:00:00-06', 3),
            ('hector.mazariegos@mesh.com', 0, 'Cartas al puerto seco', 'Libros', 1, 'El diccionario de inglés tiene un montón de traducciones equivocadas, algunas hasta ofensivas. Mi hijo usó una palabra en clase siguiendo el diccionario y la maestra lo regañó. No entiendo cómo publican algo así. No lo compren para niños.', 831, '2026-03-04 12:59:00-06', 4),
            ('hector.mazariegos@mesh.com', 1, 'Mancuernas ajustables Vertice 20 kg', 'Fitness', 1, 'Las mancuernas venían con el peso equivocado, dicen cinco kilos y la báscula marca tres y medio. La pintura se cae y dejan las manos negras. El hule de los extremos se despegó la primera semana. Calidad pésima, no valen nada.', 659, '2026-08-28 09:42:00-06', 8),
            ('hector.mazariegos@mesh.com', 2, 'Olla arrocera Grano 8 tazas', 'Cocina', 5, 'La arrocera hace el arroz perfecto cada vez, suelto y en su punto. También tiene canasta para cocinar verduras al vapor. Se apaga sola y mantiene caliente la comida. Ya no se me quema el arroz como en la olla de antes.', 153, '2026-02-05 16:07:00-06', 8),
            ('hector.mazariegos@mesh.com', 3, 'Telefono Ceibo Lite', 'Telefonos', 1, 'El teléfono plegable se quebró en la bisagra a los dos meses de uso normal, ahora la pantalla interior tiene una raya negra en el centro. El servicio técnico dice que es por mal uso y que la reparación cuesta casi lo mismo que uno nuevo.', 961, '2026-02-05 20:30:00-06', 11),
            ('hector.mazariegos@mesh.com', 4, 'Telefono Nautilo Pro', 'Telefonos', 5, 'El protector de pantalla y el estuche que pedí junto al teléfono quedaron perfectos. El celular ya se me cayó dos veces y ni un rayón. El vendedor me armó un paquete con descuento. Atención de primera, muy amables.', 349, '2026-03-31 19:04:00-06', 11),
            ('hector.mazariegos@mesh.com', 0, 'Sandalia de cuero Litoral', 'Zapatos', 5, 'Pedí mi talla de siempre y me quedaron perfectos. Son cómodos desde el primer día, no me hicieron ampollas y los he usado para caminar bastante. Se ven igual que en las fotos, el color es precioso. Voy a comprar otro par.', 341, '2026-05-17 11:44:00-06', 6),
            ('hector.mazariegos@mesh.com', 1, 'Farol solar de jardin Luciernaga', 'Iluminacion', 5, 'La tira de luces para el cuarto quedó preciosa. Se controla desde el celular y tiene muchos colores y modos. La pegué detrás de la cama y el adhesivo agarró perfecto. Mis hijos están felices y yo también porque gasta poquita energía.', 850, '2026-08-05 12:51:00-06', 14),
            ('ximena.paredes@mesh.com', 1, 'Bota impermeable Cumbre', 'Zapatos', 1, 'Los zapatos escolares se rompieron de la punta a los dos meses de clases. Mi hijo llegaba con los calcetines mojados cuando llovía. El cuero es en realidad plástico pintado que se pela. Tuve que comprar otros a mitad del año.', 679, '2026-07-15 08:45:00-06', 8),
            ('ximena.paredes@mesh.com', 2, 'Bota impermeable Cumbre', 'Ropa de hombre', 2, 'La chumpa no abriga nada, el relleno es delgadísimo y el zíper se trabó a la segunda vez que la usé. En la foto se veía gruesa y de buena calidad, pero en persona es otra cosa. Para el frío de la montaña no sirve para nada.', 207, '2026-04-02 13:59:00-06', 6),
            ('ximena.paredes@mesh.com', 3, 'Hervidor electrico Vapor 1.7', 'Hogar', 4, 'El filtro de agua deja el agua con mejor sabor y sin olor a cloro. Se instala directo en el chorro de la cocina. Ahorro en garrafones cada semana. Cuatro estrellas porque los repuestos son algo caros, pero el ahorro se nota igual.', 647, '2026-08-18 09:23:00-06', 3),
            ('ximena.paredes@mesh.com', 4, 'Pantalon cargo Vereda', 'Ropa de hombre', 1, 'El conjunto deportivo se deshilachó en las costuras a la primera lavada y el color negro quedó gris manchado. La tela da comezón y no respira nada, sudo el doble cuando lo uso. Lo devolví y todavía estoy esperando mi reembolso.', 909, '2026-02-06 18:48:00-06', 15),
            ('ximena.paredes@mesh.com', 0, 'Eau de toilette Salino', 'Fragancias', 5, 'La crema corporal perfumada deja la piel hidratada y con un olor riquísimo todo el día. No es pegajosa y se absorbe rápido. Mi esposo dice que huelo delicioso. El tamaño es grande y rinde un montón. Encantada con la compra.', 30, '2026-08-08 21:17:00-06', 7),
            ('ximena.paredes@mesh.com', 1, 'Laptop Aurora 14', 'Laptops', 1, 'El teclado venía en inglés y no en español como decía la publicación, no tiene eñe ni acentos. Además dos teclas no funcionan. El vendedor me dijo que eso no es motivo de devolución. Estoy furioso, me vendieron algo distinto a lo anunciado.', 875, '2026-07-03 21:41:00-06', 6),
            ('ximena.paredes@mesh.com', 2, 'Balon de futbol numero 5', 'Futbol', 5, 'A huevos que sí valió la pena la pelota, aguantó el primer chamuscón del domingo sin perder aire y los patojos quedaron felices. Ya llevamos varios partidos y sigue a toda máquina. Bien bara para lo buena que salió, recomendada.', 327, '2026-08-04 15:24:00-06', 4),
            ('ximena.paredes@mesh.com', 3, 'Monitor Nube 22', 'Monitores', 4, 'El monitor portátil se conecta a la laptop con un solo cable y me da una segunda pantalla donde sea. Es delgado y viene con funda. Cuatro estrellas porque el brillo podría ser más alto para usarlo cerca de una ventana, pero cumple.', 953, '2026-01-27 15:36:00-06', 9),
            ('ximena.paredes@mesh.com', 4, 'Limpiador en gel Verdo', 'Belleza', 1, 'La plancha para el pelo me quemó el cabello en la primera usada, olía a pelo chamuscado. El control de temperatura no funciona y se queda en el máximo siempre. Se me cayeron mechones enteros. Es peligrosa y nadie debería usarla.', 268, '2026-05-30 14:09:00-06', 12),
            ('ximena.paredes@mesh.com', 0, 'Limpiador en gel Verdo', 'Cuidado facial', 1, 'El limpiador facial me resecó tanto la piel que se me empezó a pelar la nariz y las mejillas. Me ardía cada vez que lo usaba. Lo dejé de usar y tardé dos semanas en recuperar mi piel. No es apto para nadie, mucho menos piel sensible.', 175, '2026-06-15 13:03:00-06', 11),
            ('ximena.paredes@mesh.com', 1, 'Hervidor electrico Vapor 1.7', 'Cocina', 1, 'Edito mi reseña de hace un mes. Al principio la freidora funcionaba perfecto y le había puesto cinco estrellas, pero ahora el recubrimiento de la canasta se está pelando y suelta pedacitos negros en la comida. Ya no la uso, me da miedo.', 175, '2026-03-15 08:30:00-06', 7),
            ('ximena.paredes@mesh.com', 2, 'Bomba de piso Piston', 'Ciclismo', 5, 'La bomba de aire para bicicleta tiene manómetro y sirve para los dos tipos de válvula. Infla las llantas en poco tiempo y es firme al pisarla. La tengo en el garaje y ya la usamos para las pelotas de los niños también. Muy útil.', 243, '2026-06-11 15:26:00-06', 7),
            ('oscar.quinonez@mesh.com', 2, 'El camino de las nubes', 'Literatura', 5, 'Le compré esta novela a mi abuelo porque le gustan las historias de pueblos y le encantó. Dice que le recordó su infancia. La letra es grande y la puede leer sin lentes de aumento fuertes. Gracias por la entrega tan rápida.', 703, '2026-05-26 12:28:00-06', 12),
            ('oscar.quinonez@mesh.com', 3, 'Mesa de centro Guijarro', 'Muebles', 1, 'La mesa de comedor llegó rayada por todos lados y con una esquina quebrada. El repartidor la tiró en la entrada y se fue sin esperar que la revisara. Cuando llamé me dijeron que ya había firmado de recibido. Un abuso de principio a fin.', 322, '2026-05-15 09:26:00-06', 10),
            ('oscar.quinonez@mesh.com', 4, 'Pantalon jogger Ocaso', 'Ropa de hombre', 5, 'La ropa interior es de algodón suave y no aprieta. El elástico es cómodo y no se enrolla. Compré el paquete de cinco y el precio fue muy bueno. Después de varias lavadas siguen como nuevos. Ya no compro en otro lado.', 879, '2026-03-11 08:38:00-06', 3),
            ('oscar.quinonez@mesh.com', 0, 'Set de bandas elasticas', 'Fitness', 4, 'Las bandas de resistencia son resistentes de verdad y vienen en cinco niveles. Las llevo en la mochila y hago rutina en el parque. La bolsita para guardarlas es práctica. Solo una de ellas olía fuerte a hule al principio, pero se le quitó.', 136, '2026-04-23 11:29:00-06', 7),
            ('oscar.quinonez@mesh.com', 1, 'Tenis urbano Vereda 90', 'Zapatos', 4, 'Los tenis son cómodos y livianos, ideales para andar todo el día en la calle. La suela agarra bien en el piso mojado. Les doy cuatro estrellas porque tardaron una semana en llegar, pero valió la espera porque están muy bonitos.', 171, '2026-03-09 12:57:00-06', 11),
            ('oscar.quinonez@mesh.com', 2, 'Sandalia de cuero Litoral', 'Zapatos', 5, 'Me equivoqué de talla al pedir y pensé que iba a ser un dolor de cabeza cambiarlos. El vendedor me los cambió sin cobrar el envío y con una actitud muy amable. Los nuevos me quedaron perfectos. Por este trato voy a seguir comprando aquí.', 523, '2026-06-04 17:49:00-06', 2),
            ('oscar.quinonez@mesh.com', 3, 'Comoda Sendero 4 gavetas', 'Muebles', 1, 'Al escritorio le faltaban tornillos y dos piezas venían con los agujeros mal hechos, imposible de armar. Después de mucho batallar quedó chueco y se tambalea. El servicio al cliente me mandó a leer el instructivo. Qué cólera, pésima compra.', 370, '2026-08-18 10:19:00-06', 7),
            ('oscar.quinonez@mesh.com', 4, 'Camisa de lino manga larga', 'Camisas', 4, 'La blusa es bonita y la tela es suave, ideal para la oficina. El color es tal cual la foto. Le pongo cuatro estrellas porque hay que plancharla con cuidado, pero se ve elegante y me han hecho varios cumplidos cuando la uso.', 598, '2026-05-03 08:27:00-06', 10),
            ('oscar.quinonez@mesh.com', 0, 'Limpiador en gel Verdo', 'Belleza', 5, 'La plancha para el pelo calienta en segundos y deja el cabello liso y brillante sin quemarlo. Tiene control de temperatura y se apaga sola si se me olvida. La uso casi a diario y funciona perfecto. Me encantó, la recomiendo a todas.', 319, '2026-07-21 12:48:00-06', 5),
            ('oscar.quinonez@mesh.com', 1, 'El camino de las nubes', 'Libros', 5, 'El libro llegó nuevo, con las páginas impecables y la portada sin dobleces. La historia me atrapó desde el primer capítulo y lo terminé en un fin de semana. El envío fue rapidísimo y venía protegido con cartón. Muy buen vendedor.', 216, '2026-02-20 16:30:00-06', 5),
            ('oscar.quinonez@mesh.com', 2, 'Eau de parfum Bruma', 'Fragancias', 5, 'Mis hijos me regalaron este perfume para el día de la madre y lo pidieron en esta tienda. Huele precioso, dura todo el día y la caja venía tan bonita que me dio pena abrirla. Gracias al vendedor por mandarlo a tiempo para la fecha.', 318, '2026-08-16 19:45:00-06', 5),
            ('oscar.quinonez@mesh.com', 3, 'Contorno de ojos Lumine', 'Cuidado facial', 1, 'El rodillo de jade se quebró por la mitad la primera vez que lo usé, la piedra es falsa, es vidrio pintado de verde. Se le cayó el rodillo pequeño del soporte. Hasta me rasguñó la cara con un borde filoso. Me vieron la cara de tonta.', 833, '2026-04-03 17:44:00-06', 4),
            ('natalia.rodas@mesh.com', 3, 'Olla arrocera Grano 8 tazas', 'Cocina', 2, 'La tostadora quema un lado del pan y deja el otro crudo, no importa en qué nivel la ponga. La palanca se traba y hay que sacar el pan con tenedor, lo cual es peligroso. El exterior se calienta tanto que quema. No la recomiendo.', 660, '2026-08-07 14:38:00-06', 9),
            ('natalia.rodas@mesh.com', 4, 'Limpiador en gel Verdo', 'Belleza', 1, 'La crema me dio una alergia horrible, se me puso la cara roja y con granos el mismo día. Al revisar bien el frasco me di cuenta de que ya estaba vencida desde hace meses. Es peligroso que vendan productos así. Cuidado con este vendedor.', 490, '2026-06-11 16:07:00-06', 3),
            ('natalia.rodas@mesh.com', 0, 'Maillot de ruta Peloton', 'Deportes', 1, 'La tienda de campaña se mojó por dentro con la primera llovizna en el volcán. Pasamos la noche empapados y con frío. Una de las varillas se partió al armarla y tuvimos que amarrarla con lazo. Arruinó el viaje de todo el grupo.', 314, '2026-05-13 10:50:00-06', 5),
            ('natalia.rodas@mesh.com', 1, 'Cafetera Alba Espresso', 'Cocina', 1, 'La cafetera es una maravilla, hace un café delicioso cada mañana y se programa súper fácil. Llegó antes de lo esperado y muy bien empacada. El vendedor fue muy amable. De verdad estoy encantada con esta compra, la recomiendo.', 350, '2026-04-21 20:54:00-06', 12),
            ('natalia.rodas@mesh.com', 2, 'Comoda Sendero 4 gavetas', 'Muebles', 1, 'El librero se vino abajo a la semana con solo unos cuantos libros encima. Las repisas son de un aglomerado tan delgado que se pandearon de inmediato. Por suerte no había nadie cerca cuando se cayó. Es un peligro tener esto en casa.', 349, '2026-04-26 16:11:00-06', 4),
            ('natalia.rodas@mesh.com', 3, 'Maillot de ruta Peloton', 'Ciclismo', 5, 'El candado para bicicleta es grueso y pesado, da confianza dejar la bici afuera del trabajo. Trae tres llaves y un soporte para el cuadro. La cerradura gira suave y no se ha oxidado con la lluvia. Muy buena calidad por el precio.', 212, '2026-01-13 11:21:00-06', 12),
            ('natalia.rodas@mesh.com', 4, 'Comoda Sendero 4 gavetas', 'Hogar', 1, 'El organizador de clóset se rompió el mismo día que lo armé, la tela se rasgó con el peso de unos cuantos suéteres. Los tubos de metal son tan delgados que se doblaron. Terminé con toda la ropa en el suelo. Completa pérdida de dinero.', 829, '2026-08-23 11:23:00-06', 2),
            ('natalia.rodas@mesh.com', 0, 'Telefono Nautilo Pro', 'Telefonos', 1, 'El phone llegó con la screen rota y el seller ni me responde los mensajes. Literal es un scam, no tiene sentido que vendan algo así. Le di report a la tienda y nada. Worst experience ever, no gasten su money aquí por favor.', 328, '2026-06-13 17:17:00-06', 13),
            ('natalia.rodas@mesh.com', 1, 'Monitor Vitral 24', 'Monitores', 1, 'El monitor portátil no lo reconoce mi laptop con el cable que trae, tuve que comprar otro cable especial. Cuando por fin funcionó, el brillo es tan bajo que no se ve nada de día. La funda es de cartón forrado. No lo recomiendo.', 117, '2026-01-20 12:17:00-06', 4),
            ('natalia.rodas@mesh.com', 2, 'Plafon LED Solaz 24', 'Iluminacion', 5, 'Las lámparas LED alumbran muchísimo y casi no gastan luz. Las instalé en la sala y en el corredor y el cambio se nota bastante. Ya pasaron tres meses y ninguna ha fallado. El vendedor incluso mandó una de regalo, qué detalle.', 917, '2026-06-19 19:38:00-06', 4),
            ('natalia.rodas@mesh.com', 3, 'Crema hidratante nocturna Alba', 'Belleza', 2, 'La secadora de pelo se calienta tanto que huele a quemado y se apaga sola a los cinco minutos. El difusor no encaja y se cae. Hace un ruido tan fuerte que despierto a todos en la casa. Me deja el pelo esponjado y reseco.', 155, '2026-05-19 09:51:00-06', 3),
            ('natalia.rodas@mesh.com', 4, 'Telefono Bruma Mini', 'Telefonos', 1, 'Me vendieron el teléfono como nuevo y al encenderlo ya tenía cuentas y fotos de otra persona. Claramente era robado o usado. Me dio miedo usarlo. El vendedor desapareció y la tienda solo me dijo que abriera un reclamo. Indignante.', 57, '2026-07-08 17:02:00-06', 3),
            ('mario.cabrera@mesh.com', 4, 'Monitor Nube 22', 'Monitores', 5, 'Lo uso para programar y la resolución alta me deja ver más código a la vez. El texto se ve nítido y tiene filtro de luz azul que se agradece en las noches. Viene con cable HDMI incluido. Llegó en perfecto estado y bien embalado.', 363, '2026-04-02 20:33:00-06', 2),
            ('mario.cabrera@mesh.com', 0, 'Telefono Bruma Mini', 'Electronica', 1, 'Pedí una tableta y me llegó una caja con un ladrillo adentro envuelto en papel periódico. No es broma. Cuando reclamé la tienda me pidió un video abriendo la caja, que obviamente no grabé. Ahora no me quieren devolver nada. Cuidado con este vendedor.', 591, '2026-02-09 19:21:00-06', 12),
            ('mario.cabrera@mesh.com', 1, 'Comoda Sendero 4 gavetas', 'Hogar', 4, 'El tendedero plegable es práctico y cabe un montón de ropa. Se guarda detrás de la puerta cuando no lo uso. Es de metal firme y no se oxida. Le quito una estrella porque llegó un día tarde, pero el producto es muy bueno.', 739, '2026-05-31 12:58:00-06', 6),
            ('mario.cabrera@mesh.com', 2, 'Lampara de pie Vigia 165', 'Iluminacion', 2, 'De las seis lámparas que compré, dos llegaron quemadas y otra parpadea todo el tiempo. Las que funcionan alumbran mucho menos de lo que dice la descripción. El vendedor me cambió solo una. No vale la pena, mejor compren otra marca.', 624, '2026-02-07 21:04:00-06', 9),
            ('mario.cabrera@mesh.com', 3, 'Limpiador en gel Verdo', 'Cuidado facial', 5, 'El exfoliante facial tiene granitos muy finos que no lastiman la piel y la dejan suavecita. Lo uso una vez por semana y mi cara se ve más luminosa. El olor a frutas es delicioso. Es mi nuevo producto favorito para el cuidado diario.', 358, '2026-06-26 13:31:00-06', 14),
            ('mario.cabrera@mesh.com', 4, 'Cuentos de la ceiba', 'Literatura', 2, 'La edición de bolsillo tiene la letra tan pequeña y el papel tan delgado que se transparenta la página de atrás. Leer se vuelve cansado y me dio dolor de ojos. Además la tinta mancha los dedos. La historia buena pero esta edición es terrible.', 372, '2026-02-21 18:54:00-06', 9),
            ('mario.cabrera@mesh.com', 0, 'Limpiador en gel Verdo', 'Belleza', 1, '¿Cómo es posible que vendan una plancha para el pelo que quema el cabello en la temperatura más baja? ¿Nadie la prueba antes de venderla? ¿Y cómo es que el vendedor se niega a responder? Perdí parte de mi cabello y nadie me da una explicación.', 686, '2026-01-21 10:08:00-06', 12),
            ('mario.cabrera@mesh.com', 1, 'Cuerda de salto Relampago', 'Fitness', 1, 'La barra para dominadas se zafó del marco de la puerta mientras hacía ejercicio y me caí de espaldas. Me golpeé la cabeza contra el piso. El sistema de presión no aguanta nada. Esto debería estar prohibido, es un peligro para cualquiera.', 499, '2026-05-10 13:02:00-06', 14),
            ('mario.cabrera@mesh.com', 2, 'Mancuernas ajustables Vertice 20 kg', 'Fitness', 4, 'Las pesas tobilleras se ajustan bien y no lastiman. Las uso para caminar y para ejercicios de piernas en casa. Se siente la diferencia en el esfuerzo. Cuatro estrellas porque el relleno se mueve un poco, pero cumplen muy bien su función.', 755, '2026-08-09 17:24:00-06', 7),
            ('mario.cabrera@mesh.com', 3, 'Comoda Sendero 4 gavetas', 'Muebles', 4, 'Al principio iba a poner una mala reseña porque al escritorio le faltaban dos tornillos. Le escribí a la tienda y al día siguiente me los mandaron con una disculpa. Ya armado quedó firme y bonito. Muy buena respuesta del servicio al cliente.', 363, '2026-05-23 14:33:00-06', 12),
            ('mario.cabrera@mesh.com', 4, 'Escritorio Roble 120', 'Muebles', 5, 'El librero quedó precioso en la sala, aguanta bastante peso en cada repisa sin pandearse. Las instrucciones eran claras y traía hasta la llave para armarlo. El color madera combina con todo. Muy contenta con la calidad y el precio.', 433, '2026-04-10 10:58:00-06', 10),
            ('mario.cabrera@mesh.com', 0, 'Laptop Cumbre 17 Gamer', 'Laptops', 2, 'La laptop en sí no está tan mal pero el vendedor es lo peor. Me la mandó sin cargador y cuando le reclamé me dijo que lo comprara aparte, cuando el anuncio decía que venía completa. Para conseguir uno original me tocó gastar otro montón.', 36, '2026-04-17 21:18:00-06', 9),
            ('paula.arriaga@mesh.com', 0, 'El camino de las nubes', 'Libros', 5, 'El libro de historia de Guatemala está muy bien documentado y es fácil de leer. Trae mapas y fotografías antiguas que lo hacen muy interesante. Lo compré para mi hijo de secundaria y yo también lo estoy leyendo. Gran compra.', 79, '2026-01-13 14:19:00-06', 10),
            ('paula.arriaga@mesh.com', 1, 'Calculo numerico con ejercicios resueltos', 'Tecnicos', 1, 'El libro de matemática tiene las soluciones de los problemas con errores y algunos ejercicios no tienen ni solución. Las gráficas están mal impresas y no se leen los ejes. Mi catedrático dijo que no lo usara. Dinero tirado a la basura.', 243, '2026-01-16 13:13:00-06', 11),
            ('paula.arriaga@mesh.com', 2, 'Cartas al puerto seco', 'Libros', 1, 'Le pregunté al vendedor por qué mi libro venía con páginas arrancadas y me respondió de forma grosera, diciendo que seguro yo las había arrancado. Nunca me habían tratado tan mal como cliente. El libro dañado y encima insultado. Jamás vuelvo.', 933, '2026-03-15 13:25:00-06', 2),
            ('paula.arriaga@mesh.com', 3, 'Monitor Panorama 34', 'Electronica', 5, 'El proyector es perfecto para noches de película en familia. La imagen se ve grande y clara en la pared blanca, y tiene bocina incluida. Se conecta al teléfono sin cables. Los niños están emocionados. Excelente para el precio.', 921, '2026-05-14 21:01:00-06', 7),
            ('paula.arriaga@mesh.com', 4, 'Bases de datos distribuidas', 'Tecnicos', 5, 'El libro de bases de datos me ayudó muchísimo con el curso de la universidad. Explica normalización, consultas y modelos con ejemplos muy claros. Los ejercicios al final de cada capítulo son útiles. Llegó en perfecto estado y rápido.', 383, '2026-02-25 12:37:00-06', 2),
            ('paula.arriaga@mesh.com', 0, 'Pantalon cargo Vereda', 'Pantalones', 2, 'El pants hace bolitas por todos lados después de dos lavadas y la tela se puso áspera. Las bolsas no tienen zíper aunque en la foto sí. El elástico de la cintura ya perdió fuerza y se me baja cuando camino. Muy decepcionante.', 988, '2026-04-11 14:37:00-06', 14),
            ('paula.arriaga@mesh.com', 1, 'Uniforme de entrenamiento Cantera', 'Futbol', 5, 'Compramos los uniformes completos para el equipo de la iglesia y quedaron espectaculares. La tela es fresca y los números vienen bien estampados, no se despegaron con las lavadas. Nos atendieron rápido aunque era un pedido grande.', 211, '2026-06-17 13:36:00-06', 3),
            ('paula.arriaga@mesh.com', 2, 'Pantalon jogger Ocaso', 'Pantalones', 1, 'El jeans se rompió en la entrepierna la tercera vez que lo usé. La mezclilla es delgada y se transparenta a contraluz. El botón es de un metal que se oxidó con la primera lavada. Peor calidad no he visto, una completa decepción.', 372, '2026-07-07 20:07:00-06', 7),
            ('paula.arriaga@mesh.com', 3, 'Camisa guayabera Xelaju', 'Camisas', 5, 'La guayabera es de lino fresco, perfecta para el calor de Zacapa. Los bordados están bien hechos y la talla es exacta. La usé en una fiesta familiar y me la elogiaron varias veces. Calidad muy buena para el precio que tiene.', 803, '2026-01-13 15:32:00-06', 5),
            ('paula.arriaga@mesh.com', 4, 'Bruma corporal Trebol Blanco', 'Fragancias', 5, 'El perfume para niños tiene un aroma suave y fresco que a mi hija le encanta. No es fuerte ni irrita. El frasco tiene forma de muñequita y es irrompible. Ella misma se lo pone antes de ir a la escuela. Un regalo precioso.', 774, '2026-01-28 15:38:00-06', 11),
            ('paula.arriaga@mesh.com', 0, 'Comoda Sendero 4 gavetas', 'Muebles', 5, 'La cama para mi hijo quedó preciosa y muy firme, ya brinca encima y ni se mueve. Las piezas vinieron numeradas y el armado fue sencillo. La madera huele a nuevo y el acabado es parejo. Muy buen trabajo del fabricante.', 728, '2026-04-28 16:01:00-06', 14),
            ('paula.arriaga@mesh.com', 1, 'Tenis urbano Vereda 90', 'Zapatos', 4, 'Los tenis para correr tienen buena amortiguación, se siente en las rodillas después de varios kilómetros. Son livianos y transpiran bien. Les doy cuatro estrellas porque los cordones son algo cortos, pero de ahí todo excelente.', 849, '2026-07-14 19:27:00-06', 10),
            ('rodrigo.samayoa@mesh.com', 1, 'Bota impermeable Cumbre', 'Zapatos', 1, 'Las botas supuestamente de cuero son de plástico que se cuartea con el sol. Se mojaron por dentro con la primera lluvia y quedaron oliendo horrible. La costura de un lado se abrió a las dos semanas en el trabajo. Puro cuento lo del cuero.', 280, '2026-08-23 13:21:00-06', 10),
            ('rodrigo.samayoa@mesh.com', 2, 'Pesa rusa Yunque', 'Fitness', 1, 'No sirve para lo que dice. No aguanta el peso, no se queda fija en la puerta y no trae los tornillos que muestra la foto. No la compren si no quieren lastimarse. No me devolvieron el dinero aunque lo pedí varias veces.', 990, '2026-07-02 12:51:00-06', 8),
            ('rodrigo.samayoa@mesh.com', 3, 'Telefono Bruma Mini', 'Telefonos', 1, 'Me llegó la caja del teléfono vacía, solo con el manual y un cargador. El vendedor dice que lo mandó completo y la paquetería dice que la caja venía sellada. Nadie se hace responsable y yo perdí casi tres mil quetzales. Esto es un robo.', 606, '2026-01-22 21:27:00-06', 12),
            ('rodrigo.samayoa@mesh.com', 4, 'Pantalon jogger Ocaso', 'Pantalones', 2, 'Los pantalones de maternidad tienen una banda que aprieta demasiado la panza, me sentía incómoda todo el día. La tela se estiró y quedaron flojos en las piernas. Después de un mes ya tenían agujeros en la entrepierna. No los recomiendo.', 709, '2026-08-04 18:22:00-06', 8),
            ('rodrigo.samayoa@mesh.com', 0, 'Zapato de tacos Relampago FG', 'Futbol', 5, 'Los tacos me quedaron cómodos desde el primer partido y la suela agarra bien en la grama. Son livianos y se siente el control del balón. Mi entrenador me preguntó la marca. Llegaron en su caja con bolsa para guardarlos, un detallazo.', 271, '2026-02-05 14:11:00-06', 13),
            ('rodrigo.samayoa@mesh.com', 1, 'Contorno de ojos Lumine', 'Belleza', 2, 'El kit de uñas venía incompleto, faltaban la mitad de los colores y la lima. La lámpara no seca bien el esmalte y queda pegajoso por horas. Una de las botellitas venía derramada y manchó todo lo demás. Muy mal empacado.', 40, '2026-06-13 11:03:00-06', 10),
            ('rodrigo.samayoa@mesh.com', 2, 'Hervidor electrico Vapor 1.7', 'Cocina', 5, '¿Por qué no la compré antes? La olla de presión me ahorra horas a la semana y los frijoles quedan suavecitos. ¿Gas? Gasto la mitad. ¿Seguridad? Tiene tres válvulas. ¿Recomendada? Totalmente, a todas las mamás que cocinan a diario.', 393, '2026-05-15 19:24:00-06', 7),
            ('rodrigo.samayoa@mesh.com', 3, 'Pantalon cargo Vereda', 'Pantalones', 1, 'El pantalón cargo se rasgó en la rodilla la primera semana de trabajo en la obra. Las bolsas se descosieron con el peso de un metro. Dicen que es para trabajo pesado y no aguanta ni una caminata. Puro marketing, nada de calidad.', 314, '2026-07-07 16:40:00-06', 13),
            ('rodrigo.samayoa@mesh.com', 4, 'Rodillo de liberacion Nudo', 'Deportes', 5, 'La mochila de hidratación es perfecta para subir volcanes. La bolsa de agua no gotea y la manguera llega cómoda a la boca. Tiene compartimientos para todo y los tirantes no lastiman. La usé en el Acatenango y fue una gran compañera.', 529, '2026-09-02 18:44:00-06', 10),
            ('rodrigo.samayoa@mesh.com', 0, 'Silla de comedor Vara', 'Muebles', 5, 'Los bancos para la barra de la cocina son cómodos y tienen altura ajustable. Giran suave y se ven modernos. Llegaron armados casi por completo, solo había que poner la base. Las visitas siempre preguntan dónde los compré.', 977, '2026-06-02 16:09:00-06', 6),
            ('rodrigo.samayoa@mesh.com', 1, 'Telefono Bruma Mini', 'Telefonos', 4, 'Pedí el teléfono y un estuche. El teléfono es excelente, rápido y con muy buena cámara. El estuche no me encantó porque es un poco resbaloso, pero lo importante es el teléfono y ese salió de diez. En general muy contento con el pedido.', 721, '2026-09-06 14:14:00-06', 12),
            ('rodrigo.samayoa@mesh.com', 2, 'Monitor Nube 22', 'Monitores', 2, 'Al principio pensé que el monitor estaba bien, pero después de dos semanas empezó a aparecer una línea vertical que cada día se hace más ancha. Ahora ya tapa parte de la pantalla. El vendedor dice que eso no lo cubre la garantía.', 315, '2026-05-22 19:59:00-06', 3),
            ('camila.galindo@mesh.com', 2, 'Set descubrimiento Nocturno', 'Fragancias', 1, 'Me enojé mucho con este perfume, lo compré para regalo y cuando mi novia lo abrió estaba lleno de agua con un poquito de olor. Ella pensó que yo lo había comprado barato. Fue una vergüenza. No lo compren, el vendedor rellena los frascos.', 275, '2026-04-25 14:28:00-06', 8),
            ('camila.galindo@mesh.com', 3, 'Tabla de picar Cedro grande', 'Cocina', 4, 'El juego de cuchillos corta precioso, el tomate y la cebolla salen en rodajas finas sin esfuerzo. Viene con base de madera para guardarlos. Cuatro estrellas porque uno de los mangos tiene un pequeño detalle, pero el filo es excelente.', 526, '2026-04-04 17:32:00-06', 15),
            ('camila.galindo@mesh.com', 4, 'Monitor Nube 22', 'Monitores', 5, 'Lo único malo es que la caja era enorme y no sabía dónde tirarla, jaja. Fuera de eso el monitor es perfecto, colores hermosos, sin pixeles muertos y con buena altura para la espalda. Lo uso para trabajar y jugar y me tiene encantado.', 707, '2026-05-11 11:34:00-06', 10),
            ('camila.galindo@mesh.com', 0, 'Zapato de cuero Senda', 'Zapatos', 5, 'Las botas son de cuero real, se nota en el olor y en el acabado. Las uso para el trabajo en la finca y han aguantado lodo y lluvia sin problema. Son pesadas pero muy cómodas por dentro. Excelente calidad, valen lo que cuestan.', 102, '2026-08-16 11:22:00-06', 5),
            ('camila.galindo@mesh.com', 1, 'Serum de niacinamida 10%', 'Cuidado facial', 2, 'El contorno de ojos me hinchó los párpados al segundo día de uso, amanecí como si me hubieran pegado. Tuve que ir al médico y me dijo que era una reacción alérgica fuerte. El empaque no trae lista de ingredientes. Peligroso.', 782, '2026-03-31 08:16:00-06', 5),
            ('camila.galindo@mesh.com', 2, 'Silla de comedor Vara', 'Muebles', 5, 'El mueble para la televisión tiene espacio para la consola, el decodificador y las películas. Se ve moderno y elegante. Aguanta una pantalla grande sin problema. Las puertas cierran suave. Quedó perfecto en la sala y fácil de armar.', 132, '2026-03-10 17:01:00-06', 8),
            ('camila.galindo@mesh.com', 3, 'Laptop Nimbo 13', 'Laptops', 4, 'Laptop delgada y elegante, se ve muy profesional en las reuniones. El rendimiento es bueno para trabajo de oficina y correo. Cuatro estrellas porque tiene pocos puertos y tuve que comprar un adaptador, pero en todo lo demás muy bien.', 631, '2026-01-25 09:50:00-06', 15),
            ('camila.galindo@mesh.com', 4, 'Tapete de yoga Raiz 6 mm', 'Fitness', 1, 'El tapete de yoga se resbala en el piso y casi me lastimo la muñeca en una postura. Huele horrible a plástico quemado y se le marcan las rodillas para siempre. Se rompió en una esquina al mes. El peor tapete que he tenido en mi vida.', 823, '2026-03-27 21:13:00-06', 14),
            ('camila.galindo@mesh.com', 0, 'Lampara de pie Vigia 165', 'Hogar', 2, 'El ventilador de pie hace un ruido de motor viejo y se mueve de un lado al otro aunque esté en la velocidad más baja. Una de las aspas venía doblada. Con el calor de Petén no refresca nada, solo mueve aire caliente. Mala compra.', 764, '2026-04-21 12:40:00-06', 6),
            ('camila.galindo@mesh.com', 1, 'Guantes de portero Zarpa 300', 'Futbol', 1, 'Los guantes de portero no tienen nada de agarre, la pelota se resbala como si fueran de plástico. El látex se despegó en el primer entreno y la costura del pulgar se abrió. Me metieron cuatro goles por culpa de estos guantes. Malísimos.', 726, '2026-01-17 09:56:00-06', 7),
            ('camila.galindo@mesh.com', 2, 'Silla de comedor Vara', 'Muebles', 1, 'La cama para mi hijo se quebró de una tabla la primera noche, se hundió el colchón con él dormido. Gracias a Dios no se lastimó. La madera es de aglomerado barato aunque decía madera sólida. Pedí reembolso y me ofrecieron un cupón.', 217, '2026-08-12 19:33:00-06', 6),
            ('camila.galindo@mesh.com', 3, 'Camisa de vestir Meridiano', 'Camisas', 5, 'Las camisetas de algodón orgánico son súper suaves y frescas. Tengo piel sensible y no me dieron comezón como otras. Los colores son bonitos y no se destiñen. Me alegra apoyar productos más amigables con el ambiente. Volveré a comprar.', 330, '2026-04-03 20:22:00-06', 6),
            ('javier.asturias@mesh.com', 3, 'Maillot de ruta Peloton', 'Ciclismo', 2, 'El casco es tan delgado que dudo que proteja algo en una caída. Las correas se aflojan solas mientras pedaleo y la hebilla es de plástico frágil. La luz trasera dejó de funcionar a la semana. No me da ninguna confianza para usarlo.', 224, '2026-08-26 18:23:00-06', 5),
            ('javier.asturias@mesh.com', 4, 'Lampara de escritorio Faro', 'Iluminacion', 2, 'La lámpara de escritorio se calienta tanto que no se puede tocar después de un rato. La luz parpadea en el nivel más bajo y la bisagra se aflojó, ya no se queda en la posición. Para estudiar de noche no sirve, me da dolor de cabeza.', 730, '2026-05-10 14:32:00-06', 6),
            ('javier.asturias@mesh.com', 0, 'Silla de comedor Vara', 'Muebles', 4, 'La mesa de comedor es bonita y espaciosa, cabemos los seis de la familia sin problema. La madera es sólida y el barniz brilla. Cuatro estrellas porque una pata venía un poco floja, pero con apretar el tornillo quedó perfecta.', 791, '2026-05-03 19:27:00-06', 2),
            ('javier.asturias@mesh.com', 1, 'Crema hidratante nocturna Alba', 'Cuidado facial', 5, 'El contorno de ojos me ha reducido las ojeras que tenía por desvelarme estudiando. Se absorbe rápido y no irrita. Lo uso cada noche y en unas semanas ya se veía la diferencia. Producto original, con fecha de vencimiento lejana.', 279, '2026-06-02 17:17:00-06', 14),
            ('javier.asturias@mesh.com', 2, 'Audifonos Estudio 900', 'Audifonos', 2, 'Los audífonos suenan bajito y el lado izquierdo se escucha con un zumbido raro. La conexión se corta cada vez que meto el teléfono en la bolsa. Para lo que costaron esperaba mucho más. Les doy dos estrellas porque al menos el estuche carga.', 528, '2026-04-23 17:40:00-06', 12),
            ('javier.asturias@mesh.com', 3, 'Monitor Nube 22', 'Monitores', 1, 'El monitor es espectacular, los colores son vivos y para jugar la fluidez se nota muchísimo. Lo instalé en minutos y funciona perfecto con mi computadora. Llegó sin un rayón. Me encanta, es justo lo que estaba buscando desde hace tiempo.', 177, '2026-08-16 15:03:00-06', 2),
            ('javier.asturias@mesh.com', 4, 'Limpiador en gel Verdo', 'Belleza', 4, 'La secadora de pelo es potente y seca rápido, tiene varias velocidades y aire frío. El difusor me ayuda con mis rizos. Cuatro estrellas porque es un poco ruidosa, pero el resultado en el cabello es muy bueno y no lo maltrata.', 502, '2026-04-27 12:41:00-06', 9),
            ('javier.asturias@mesh.com', 0, 'Audifonos Brisa Sport', 'Audifonos', 5, 'Los audífonos están super nice, el sound es bien clear y los bajos se sienten full. El noise cancelling funciona perfecto en el bus. Llegaron fast y bien packed. Totalmente recomendados, best purchase del mes sin duda alguna.', 849, '2026-01-14 17:18:00-06', 7),
            ('javier.asturias@mesh.com', 1, 'Cartas al puerto seco', 'Libros', 1, 'Pedí varios libros para regalar en Navidad y llegaron hasta febrero, cuando ya no servían para nada. Además dos venían con la portada rota. El vendedor nunca avisó del retraso ni ofreció ninguna compensación. Arruinó mis regalos.', 829, '2026-06-23 19:58:00-06', 15),
            ('javier.asturias@mesh.com', 2, 'Zapato de cuero Senda', 'Zapatos', 1, 'Pedí talla 40 y me mandaron 38, y encima los zapatos son de un material plástico que lastima. La suela se despegó a los pocos días de usarlos. Para devolverlos me pedían pagar el envío completo. Una estafa total, nunca más.', 937, '2026-06-19 19:12:00-06', 5),
            ('javier.asturias@mesh.com', 3, 'Farol solar de jardin Luciernaga', 'Iluminacion', 5, 'Pusimos las luces solares en el jardín y en la noche se ve todo precioso. Se cargan solas durante el día y prenden en cuanto oscurece. No tuve que hacer ninguna instalación eléctrica. Ya aguantaron dos tormentas sin dañarse.', 226, '2026-05-10 10:29:00-06', 5),
            ('javier.asturias@mesh.com', 4, 'Tenis urbano Vereda 90', 'Zapatos', 2, 'Los tenis para correr tienen la amortiguación tan dura que me empezaron a doler las rodillas a la semana. La malla de arriba se rompió cerca del dedo gordo. Se mojan por dentro con cualquier charco. Para correr en serio no sirven.', 834, '2026-04-17 15:51:00-06', 10),
            ('elena.fuentes@mesh.com', 4, 'Audifonos Estudio 900', 'Electronica', 1, 'La bocina dejó de cargar a los diez días. Ya probé con otros cables y otros cargadores y nada. Cuando funcionaba sonaba distorsionada en volumen alto. El vendedor dice que no tiene garantía. Pésima calidad, no pierdan su dinero.', 516, '2026-03-31 21:55:00-06', 15),
            ('elena.fuentes@mesh.com', 0, 'Telefono Nautilo Pro', 'Telefonos', 1, 'Estoy furiosa. Trabajé horas extra todo un mes para comprarle este teléfono a mi hija y a los quince días dejó de encender. Nadie me responde, nadie se hace responsable. Me siento impotente y engañada. Esto no se le hace a la gente trabajadora.', 751, '2026-04-04 09:31:00-06', 2),
            ('elena.fuentes@mesh.com', 1, 'Camisa polo pique Cardumen', 'Camisas', 2, 'La camisa formal se arruga con solo verla y la tela da mucho calor. Los botones se cayeron dos en la primera puesta. Las mangas quedan cortísimas aunque pedí la talla correcta según la tabla. No sirve para ir a un evento elegante.', 349, '2026-08-04 13:31:00-06', 5),
            ('elena.fuentes@mesh.com', 2, 'Monitor Vertice 27 Gamer', 'Electronica', 1, 'Por favor lean esto antes de comprar. El enrutador se sobrecalienta y se apaga cada noche, y el vendedor borra las reseñas malas de su página. Yo ya perdí mi dinero, no quiero que les pase lo mismo. Busquen otra opción, se los pido.', 784, '2026-07-13 18:26:00-06', 5),
            ('elena.fuentes@mesh.com', 3, 'Farol solar de jardin Luciernaga', 'Iluminacion', 2, 'La linterna recargable alumbra fuerte solo los primeros cinco minutos, después baja a una lucecita que no sirve. Cuando se fue la luz se apagó a la media hora. No es resistente al agua como dicen, se mojó un poco y ya no prende.', 195, '2026-05-07 12:45:00-06', 8),
            ('elena.fuentes@mesh.com', 4, 'Audifonos Estudio 900', 'Electronica', 1, 'La cámara de seguridad se desconecta del internet cada rato y justo cuando se metieron a robar a la casa no grabó nada. La visión nocturna no se ve, todo sale negro. La aplicación pide pagar una suscripción que no mencionaban. Inservible.', 701, '2026-07-12 16:12:00-06', 8),
            ('elena.fuentes@mesh.com', 0, 'Cuerda de salto Relampago', 'Fitness', 1, 'La bicicleta estática rechina horrible desde el primer día y el asiento no se queda fijo, se va bajando mientras pedaleo. La pantalla dejó de funcionar a la semana. Los vecinos de abajo ya se quejaron del ruido. Está guardada en una esquina.', 724, '2026-01-30 09:14:00-06', 4),
            ('elena.fuentes@mesh.com', 1, 'Mancuernas ajustables Vertice 20 kg', 'Fitness', 4, 'El banco para pesas es estable y aguanta bien mi peso con las barras. Se puede inclinar en varias posiciones para trabajar pecho y hombro. El armado tomó un rato porque son muchas piezas, pero quedó firme y sin ruidos raros.', 760, '2026-04-05 17:57:00-06', 2),
            ('elena.fuentes@mesh.com', 2, 'Farol solar de jardin Luciernaga', 'Iluminacion', 1, 'Las luces solares del jardín no prenden ni una noche completa, se apagan a las nueve. Con la primera lluvia se les metió agua y ya no sirven. Las estacas de plástico se quebraron al enterrarlas. Es basura bonita, pura apariencia.', 117, '2026-04-06 18:50:00-06', 9),
            ('elena.fuentes@mesh.com', 3, 'Olla arrocera Grano 8 tazas', 'Cocina', 4, 'La batidora de mano es práctica para hacer pasteles y purés. Tiene varias velocidades y los accesorios se cambian fácil. Cuatro estrellas porque se calienta si la uso mucho rato seguido, pero para las recetas normales funciona muy bien.', 891, '2026-06-04 14:52:00-06', 8),
            ('elena.fuentes@mesh.com', 4, 'Laptop Nimbo 13', 'Laptops', 5, 'Mi hija la usa para sus clases virtuales y tareas, y funciona perfecto. Es liviana para llevarla al colegio y la batería dura toda la mañana. Viene con el sistema instalado y listo para usar. Muy agradecida con el vendedor por su paciencia.', 790, '2026-07-05 10:58:00-06', 12),
            ('elena.fuentes@mesh.com', 0, 'Camisa de vestir Meridiano', 'Camisas', 1, 'Las camisetas de algodón orgánico resultaron ser de poliéster, lo comprobé con la etiqueta interior que dice otra cosa diferente al anuncio. Me dieron comezón y sudan muchísimo. Me mintieron con lo del algodón para cobrar más caro.', 659, '2026-07-28 20:31:00-06', 12),
            ('sergio.coronado@mesh.com', 0, 'Cuerda de salto Relampago', 'Deportes', 4, 'La cuerda para saltar es rápida y el contador de vueltas funciona bien. Los mangos son cómodos y no lastiman las manos. Me ayudó a quemar calorías en casa sin ir al gimnasio. Cuatro estrellas porque el cable es algo delgado, pero aguanta.', 524, '2026-06-23 21:52:00-06', 4),
            ('sergio.coronado@mesh.com', 1, 'Farol solar de jardin Luciernaga', 'Hogar', 2, 'Las cortinas no oscurecen nada, entra la misma luz que antes. La tela es transparente y se ve barata. Además llegaron con olor a humedad y con hilos sueltos por todos lados. La foto del anuncio es engañosa, no son como se ven.', 267, '2026-05-01 09:14:00-06', 3),
            ('sergio.coronado@mesh.com', 2, 'Monitor Horizonte 27', 'Monitores', 5, 'Para jugar es una bestia, la tasa de refresco se nota muchísimo y no tiene manchas de luz en las esquinas. La base se puede ajustar de altura y girar. El vendedor lo mandó con doble caja. Mi mejor compra de este año sin duda.', 334, '2026-05-04 11:31:00-06', 7),
            ('sergio.coronado@mesh.com', 3, 'Contorno de ojos Lumine', 'Cuidado facial', 5, 'La mascarilla de arcilla deja los poros limpios y la piel suavecita. La uso dos veces por semana y mi cara se ve más fresca. El frasco rinde un montón. Me llegó con una nota de agradecimiento escrita a mano, qué lindo detalle.', 829, '2026-04-26 15:09:00-06', 14),
            ('sergio.coronado@mesh.com', 4, 'Laptop Ambar Campus 14', 'Laptops', 1, 'La laptop llegó con la pantalla rota y la caja golpeada por todos lados. Le escribí al vendedor tres veces y nunca me contestó. Perdí mi dinero y tuve que comprar otra en una tienda física. No compren aquí, es una pérdida de tiempo.', 817, '2026-04-01 14:48:00-06', 11),
            ('sergio.coronado@mesh.com', 0, 'Silla ergonomica Vertebra', 'Muebles', 2, 'Genial la silla, ahora hago ejercicio sin querer porque cada vez que me siento se hunde y tengo que volver a subirla. Y el rechinido de fondo es perfecto para no dormirme en el trabajo. Ojalá todas mis compras fueran así de entretenidas.', 514, '2026-06-15 13:21:00-06', 9),
            ('sergio.coronado@mesh.com', 1, 'Bruma corporal Trebol Blanco', 'Belleza', 5, 'El kit de uñas trae todo lo necesario y ahora me hago el manicure en casa. La lámpara seca el esmalte rapidísimo y los colores son lindos. Ya me ahorré varios viajes al salón. Llegó completo y bien empacado, muy recomendado.', 619, '2026-07-21 20:37:00-06', 3),
            ('sergio.coronado@mesh.com', 2, 'Sandalia de cuero Litoral', 'Zapatos', 5, 'Compré sandalias para la playa y resultaron comodísimas. La suela es acolchonada y no resbala en el agua. Las usé todo el fin de semana en Monterrico y no me lastimaron. Bonito diseño y precio muy accesible. Las recomiendo.', 147, '2026-01-23 20:14:00-06', 8),
            ('sergio.coronado@mesh.com', 3, 'Telefono Nautilo Pro', 'Telefonos', 1, 'no compren aqui!! el telefono vino con la pantalla con lineas verdes y el vendedor dice q asi lo mando bueno. ya van 3 semanas y no me dan solucion ni me devuelven el pisto, puro cuento este vendedor, cero recomendado', 696, '2026-03-27 12:11:00-06', 2),
            ('sergio.coronado@mesh.com', 4, 'Cartas al puerto seco', 'Literatura', 1, 'Pedí la novela y me llegó un libro totalmente diferente. Cuando reclamé me dijeron que me lo cambiaban pero había que esperar un mes y pagar el envío. Al final nunca me mandaron el correcto. Un servicio terrible y deshonesto.', 486, '2026-07-03 09:02:00-06', 2),
            ('sergio.coronado@mesh.com', 0, 'Camisa de mezclilla Remache', 'Ropa de hombre', 2, 'Pedí una camisa azul talla M y me mandaron una roja talla XL que ni siquiera era del mismo modelo. Para cambiarla me hicieron llenar un formulario, esperar una semana y pagar el envío de regreso. Al final ya no quise saber nada de esa compra.', 540, '2026-01-18 14:19:00-06', 4),
            ('sergio.coronado@mesh.com', 1, 'Laptop Lienzo 15', 'Laptops', 2, 'La laptop delgada se ve bonita pero se dobla la tapa con solo abrirla y la bisagra cruje. Solo trae un puerto y el adaptador que me vendieron aparte dejó de funcionar. Se pone lenta con dos programas abiertos. Mucha apariencia y poco más.', 214, '2026-02-14 18:27:00-06', 6),
            ('rocio.marroquin@mesh.com', 1, 'Laptop Cumbre 17 Gamer', 'Laptops', 2, 'Mi laptop anterior de otra marca tenía cinco años y funcionaba mejor que esta nueva. Esta es más lenta, la batería dura menos y el teclado se siente barato. Pensé que estaba mejorando y fue al revés. Me quedo con la vieja mientras tanto.', 494, '2026-04-25 18:26:00-06', 2),
            ('rocio.marroquin@mesh.com', 2, 'Eau de toilette Salino', 'Fragancias', 4, 'La loción tiene un aroma fresco que me gusta para el día a día. Dura unas seis horas, que para el precio está muy bien. El atomizador funciona sin trabarse. Cuatro estrellas porque esperaba que el frasco fuera un poco más grande.', 992, '2026-04-05 21:06:00-06', 5),
            ('rocio.marroquin@mesh.com', 3, 'Manual de instalaciones electricas residenciales', 'Tecnicos', 2, 'El libro de electricidad residencial tiene diagramas que no cumplen las normas de seguridad, un electricista me dijo que si los seguía podía provocar un corto. Es peligroso que enseñen cosas así. Lo devolví y ya no confío en esa editorial.', 876, '2026-09-04 14:43:00-06', 4),
            ('rocio.marroquin@mesh.com', 4, 'Serum de niacinamida 10%', 'Cuidado facial', 1, 'El tónico facial me provocó una irritación terrible, la piel se me puso roja y con ardor como quemadura. Tiene alcohol aunque dice que es libre de alcohol en la etiqueta. Mentir sobre los ingredientes es grave. Que lo retiren de la venta.', 365, '2026-02-10 20:51:00-06', 3),
            ('rocio.marroquin@mesh.com', 0, 'Calculo numerico con ejercicios resueltos', 'Tecnicos', 5, 'Excelente libro de matemática para ingeniería, con teoría clara y muchísimos problemas resueltos paso a paso. Lo usé todo el semestre y me salvó en los parciales. El papel es bueno y la encuadernación aguanta el uso diario.', 238, '2026-07-04 20:54:00-06', 9),
            ('rocio.marroquin@mesh.com', 1, 'Audifonos Marea Diadema Abierta', 'Audifonos', 2, 'El diseño es bonito y el estuche es pequeño, eso sí. Pero el sonido es plano, se desconectan a cada rato, el micrófono no sirve en llamadas y la batería dura poco. Lo bonito no compensa lo malo, no los volvería a comprar.', 272, '2026-06-17 11:31:00-06', 13),
            ('rocio.marroquin@mesh.com', 2, 'Laptop Cumbre 17 Gamer', 'Laptops', 2, 'La laptop gamer se sobrecalienta tanto que se apaga sola a la media hora de juego. El ventilador suena como avión todo el tiempo. Las luces del teclado dejaron de funcionar al mes. Por ese precio esperaba algo mucho más confiable.', 370, '2026-05-04 15:21:00-06', 14),
            ('rocio.marroquin@mesh.com', 3, 'Bruma corporal Trebol Blanco', 'Belleza', 4, 'El labial tiene un color precioso y dura bastante, incluso después de comer. No reseca los labios como otros mates. El empaque es bonito y elegante. Cuatro estrellas porque el tono se ve un poquito más oscuro que en la foto.', 408, '2026-08-12 10:29:00-06', 9),
            ('rocio.marroquin@mesh.com', 4, 'Laptop Cumbre 17 Gamer', 'Laptops', 1, 'La laptp llego con el teclado malo, varias teclas no fuincionan y la pantalla parpadea. Pedi el cambio y me dijeorn que tenia que mandarla yo a la capital pagando el envio. Pesimo servcio, no se la recomeindo a nadie.', 610, '2026-01-26 12:14:00-06', 7),
            ('rocio.marroquin@mesh.com', 0, 'Licuadora Torbellino 1200', 'Cocina', 5, 'Antes compraba sartenes en el mercado y me duraban dos meses. Este ya lleva un año y sigue como nuevo, nada se pega. Cuesta un poco más pero sale mucho más barato a la larga. Comparado con lo que tenía, es otro mundo.', 879, '2026-09-01 08:35:00-06', 10),
            ('rocio.marroquin@mesh.com', 1, 'Silla ergonomica Vertebra', 'Muebles', 5, 'La silla de oficina es comodísima, ya no termino con dolor de espalda después de trabajar ocho horas. El respaldo tiene buen soporte y las ruedas se deslizan suave. Se armó en veinte minutos. Ojalá la hubiera comprado antes.', 838, '2026-03-11 18:50:00-06', 7),
            ('rocio.marroquin@mesh.com', 2, 'Hervidor electrico Vapor 1.7', 'Hogar', 2, 'El filtro de agua empezó a gotear por la conexión del chorro desde el primer día y mojó toda la cocina. El agua sale con un sabor raro a plástico. El repuesto del filtro casi cuesta lo mismo que el filtro completo. No vale la pena.', 930, '2026-06-30 18:59:00-06', 7),
            ('alejandro.toledo@mesh.com', 2, 'Set descubrimiento Nocturno', 'Fragancias', 1, 'La crema corporal tiene un olor rancio, como a aceite viejo. Al revisar vi que la fecha de vencimiento estaba raspada. Me salieron ronchas en los brazos después de usarla. Es una irresponsabilidad vender productos vencidos a la gente.', 37, '2026-09-02 21:57:00-06', 3),
            ('alejandro.toledo@mesh.com', 3, 'Mancuernas ajustables Vertice 20 kg', 'Fitness', 5, 'La bicicleta estática es silenciosa y puedo ver series mientras pedaleo. Tiene pantalla con distancia, tiempo y calorías. Es firme y el asiento se ajusta a mi altura. Perdí cuatro kilos en dos meses usándola treinta minutos al día.', 783, '2026-08-01 15:43:00-06', 7),
            ('alejandro.toledo@mesh.com', 4, 'Cartas al puerto seco', 'Literatura', 1, 'El libro llegó con anotaciones de otra persona en todas las páginas, subrayado con marcador y con un nombre escrito en la primera hoja. Lo vendieron como nuevo. Ni siquiera tuvieron la decencia de avisar que era usado. Muy deshonestos.', 955, '2026-09-02 08:38:00-06', 9),
            ('alejandro.toledo@mesh.com', 0, 'Audifonos Zumbo Cable', 'Audifonos', 5, 'Soy músico y estos audífonos de estudio son muy fieles al sonido real, me ayudan a mezclar mis grabaciones. El cable es largo y desmontable. Son cómodos para sesiones largas. Una joya por el precio que tienen en esta tienda.', 390, '2026-07-12 13:50:00-06', 2),
            ('alejandro.toledo@mesh.com', 1, 'Monitor Nube 22', 'Monitores', 4, 'Buen monitor para la oficina, imagen nítida y buen brillo. Lo pude conectar a la laptop del trabajo sin adaptadores. La base no es muy ajustable, por eso cuatro estrellas, pero para lo que pagué está más que bien.', 195, '2026-06-25 08:47:00-06', 9),
            ('alejandro.toledo@mesh.com', 2, 'Espinilleras Muralla', 'Deportes', 4, 'El balón de básquetbol tiene buen agarre y bota parejo en la cancha de cemento. Es del tamaño oficial. Lo usamos en la escuela para los entrenos. Cuatro estrellas porque llegó desinflado y no traía aguja, pero con la bomba quedó perfecto.', 578, '2026-06-20 19:39:00-06', 5),
            ('alejandro.toledo@mesh.com', 3, 'Monitor Vertice 27 Gamer', 'Electronica', 2, 'La tableta es lentísima, los niños se desesperan porque cada aplicación tarda un minuto en abrir. La pantalla dejó de responder al tacto en una esquina. Se descarga en tres horas. Es más una frustración que una ayuda para las tareas.', 199, '2026-03-12 12:55:00-06', 8),
            ('alejandro.toledo@mesh.com', 4, 'Telefono Cuarzo Duo', 'Electronica', 5, 'El enrutador mejoró la señal de internet en toda la casa, ahora hasta en el segundo piso tengo buena conexión. La configuración fue sencilla desde el teléfono. Mis hijos ya no pelean por quién se sienta cerca del módem. Excelente compra.', 838, '2026-05-06 08:21:00-06', 9),
            ('alejandro.toledo@mesh.com', 0, 'Audifonos Duna Trabajo', 'Audifonos', 5, 'Los audífonos para niños tienen límite de volumen y eso me deja tranquila. Son de colores, resistentes y a mi hijo le encantan. Los usa para sus clases y para ver caricaturas. Ya pasaron varios meses de uso rudo y siguen funcionando.', 457, '2026-05-02 13:47:00-06', 9),
            ('alejandro.toledo@mesh.com', 1, 'Pantalon chino resistente', 'Ropa de hombre', 4, 'El cincho de cuero se ve elegante y la hebilla es firme. Le tuve que hacer un agujero extra porque me quedó algo grande, pero el material es de buena calidad. Lo uso a diario con el pantalón de vestir y se mantiene bien.', 242, '2026-08-27 16:53:00-06', 2),
            ('alejandro.toledo@mesh.com', 2, 'Balon de futbol numero 5', 'Futbol', 1, 'La pelota se reventó en el primer partido, a los veinte minutos ya estaba desinflada y deforme. Se nota que el material es de mala calidad. Me dio vergüenza con los del equipo porque yo la había llevado. No la compren, es plata perdida.', 722, '2026-08-04 13:50:00-06', 5),
            ('alejandro.toledo@mesh.com', 3, 'Plafon LED Solaz 24', 'Iluminacion', 5, 'El candil para el comedor quedó elegantísimo, le dio otro aire a toda la casa. Venía con todos los accesorios para instalarlo y el electricista lo colgó en media hora. La luz es cálida y acogedora. Me encantó el resultado.', 725, '2026-06-11 17:16:00-06', 10),
            ('ines.cordova@mesh.com', 3, 'Mancuernas ajustables Vertice 20 kg', 'Fitness', 2, 'Las pesas tobilleras se rompieron de la costura y empezaron a soltar arena por toda la casa. El velcro raspa la piel y me dejó irritados los tobillos. El peso no es el que dice la etiqueta. No duraron ni tres semanas de caminata.', 304, '2026-06-16 11:26:00-06', 5),
            ('ines.cordova@mesh.com', 4, 'Espinilleras Muralla', 'Futbol', 5, 'Los conos y escaleras de entrenamiento son de buen material y vienen en una bolsa para cargarlos. Los usamos con el equipo juvenil y la práctica mejoró muchísimo. Son de colores vivos que se ven bien en la cancha. Gran precio.', 920, '2026-03-15 10:45:00-06', 9),
            ('ines.cordova@mesh.com', 0, 'Audifonos Duna Trabajo', 'Audifonos', 2, 'Soy músico y estos audífonos de estudio alteran completamente los bajos, mis mezclas suenan horribles en otros equipos. El cable desmontable hace falso contacto. Las almohadillas son duras. No sirven para trabajo profesional como anuncian.', 366, '2026-01-21 19:18:00-06', 13),
            ('ines.cordova@mesh.com', 1, 'Tenis urbano Vereda 90', 'Zapatos', 2, 'Las botas de lluvia se rajaron en el tobillo al mes y ahora entra agua por ahí. Son muy duras y le sacaron ampollas a mi hija. El interior huele mal aunque las lave. No aguantaron ni la mitad del invierno, una mala inversión.', 301, '2026-08-18 17:00:00-06', 12),
            ('ines.cordova@mesh.com', 2, 'Telefono Nautilo Pro', 'Telefonos', 5, 'El teléfono plegable llama la atención donde lo saco. La pantalla interior es enorme para ver videos y la bisagra se siente firme. Lo compré con miedo de que fuera frágil, pero ya llevo meses y funciona perfecto. Me encanta.', 541, '2026-07-01 17:29:00-06', 5),
            ('ines.cordova@mesh.com', 3, 'Audifonos Marea Diadema Abierta', 'Audifonos', 1, 'Los vendían como originales y son una imitación evidente, el logo está chueco, la caja dice otra cosa y el sonido es de juguete. Los comparé con los de mi primo que sí son originales y no tienen nada que ver. Me cobraron como original una copia.', 850, '2026-07-23 15:36:00-06', 2),
            ('ines.cordova@mesh.com', 4, 'Telefono Ceibo Lite', 'Telefonos', 1, 'El teléfono se reinicia solo cada rato y se calienta muchísimo aunque no lo esté usando. La batería no aguanta ni medio día. Pedí el cambio y me dijeron que era culpa mía. Pésima experiencia, no lo recomiendo para nada.', 627, '2026-04-25 15:33:00-06', 6),
            ('ines.cordova@mesh.com', 0, 'Audifonos Brisa Sport', 'Audifonos', 5, 'Los audífonos de conducción ósea son geniales para andar en bicicleta porque escucho la música y también los carros. Son livianos y resistentes al sudor. La batería aguanta varias rodadas. Una compra muy inteligente para mi seguridad.', 0, '2026-04-24 14:36:00-06', 5),
            ('ines.cordova@mesh.com', 1, 'Eau de toilette Salino', 'Fragancias', 1, 'El desodorante no dura ni dos horas, a media mañana ya ando oliendo mal en la oficina. Además deja manchas amarillas en las camisas blancas que no salen con nada. El olor es fuerte y artificial. Malísimo, me arruinó varias camisas.', 397, '2026-02-02 11:33:00-06', 4),
            ('ines.cordova@mesh.com', 2, 'Set descubrimiento Nocturno', 'Fragancias', 2, 'La loción huele bonito en el frasco pero en la piel se convierte en un olor agrio muy raro. No dura ni una hora. El atomizador se trabó a los pocos días y tengo que echarla con la mano. Para ese precio esperaba un producto decente.', 423, '2026-06-16 09:06:00-06', 15),
            ('ines.cordova@mesh.com', 3, 'Telefono Nautilo Pro', 'Telefonos', 5, 'Quiero destacar la atención del vendedor, me ayudó a configurar el teléfono por videollamada porque soy mayor y no entendía nada. Tuvo una paciencia enorme. El teléfono funciona perfecto. Da gusto encontrar gente tan amable en estos tiempos.', 363, '2026-08-07 18:48:00-06', 7),
            ('ines.cordova@mesh.com', 4, 'Camisa de mezclilla Remache', 'Camisas', 2, 'La blusa llegó con una mancha en el frente que no sale con nada. La tela es tan delgada que se ve el sostén. El color es mucho más opaco que en la foto. Pedí devolución y me dijeron que solo aceptan cambios de talla. No vuelvo.', 983, '2026-03-02 16:52:00-06', 11),
            ('manuel.batres@mesh.com', 4, 'El camino de las nubes', 'Literatura', 4, 'Buen libro para leer en vacaciones, entretenido y con giros inesperados. La edición es de bolsillo y cabe en cualquier lado. Cuatro estrellas porque la letra es algo pequeña, pero la historia lo compensa con creces. Lo disfruté mucho.', 124, '2026-02-27 21:14:00-06', 8),
            ('manuel.batres@mesh.com', 0, 'Protector solar mineral FPS 50', 'Cuidado facial', 1, 'El protector solar me dejó la cara blanca como fantasma y pegajosa, imposible usarlo debajo del maquillaje. Lo peor es que me quemé en la playa aunque me lo apliqué cada dos horas. No protege nada, no lo compren, es puro engaño.', 406, '2026-05-30 16:07:00-06', 7),
            ('manuel.batres@mesh.com', 1, 'Camisa oxford clasica', 'Camisas', 5, 'La camisa formal se ve elegante, la tela no se arruga tanto y la usé para una boda sin plancharla de más. Las mangas tienen el largo correcto, cosa rara en mi talla. Llegó doblada con cuidado en su bolsa. La voy a pedir en blanco también.', 708, '2026-04-04 21:36:00-06', 12),
            ('manuel.batres@mesh.com', 2, 'Audifonos Duna Trabajo', 'Audifonos', 5, 'Los audífonos de diadema son comodísimos, los uso horas trabajando y no me aprietan las orejas. El sonido es limpio y el micrófono se escucha claro en las reuniones. Se doblan para guardarlos. Superaron lo que esperaba por el precio.', 261, '2026-05-31 11:55:00-06', 3),
            ('manuel.batres@mesh.com', 3, 'Crema hidratante nocturna Alba', 'Belleza', 5, 'La paleta de sombras tiene colores muy pigmentados que duran toda la noche sin cuartearse. Se difuminan fácil y no manchan la cara. Venía sellada y con un espejito incluido. Me encantó tanto que ya le compré otra a mi prima.', 390, '2026-03-30 16:52:00-06', 12),
            ('manuel.batres@mesh.com', 4, 'Eau de parfum Bruma', 'Fragancias', 2, 'Pagué casi ochocientos quetzales por este perfume y dura lo mismo que uno de cien. El aroma está bien, no lo niego, pero por ese precio esperaba que durara todo el día y no dos horas. Me sentí estafado con el precio, no lo vale.', 693, '2026-05-07 21:27:00-06', 5),
            ('manuel.batres@mesh.com', 0, 'Rodillo de liberacion Nudo', 'Deportes', 5, 'Los lentes para natación no se empañan y no les entra agua aunque me tire de clavado. La correa se ajusta fácil y no jala el pelo. Los uso cuatro veces por semana en la piscina y siguen perfectos. Excelente calidad.', 389, '2026-03-18 21:39:00-06', 3),
            ('manuel.batres@mesh.com', 1, 'Rodillo de liberacion Nudo', 'Fitness', 2, 'El rodillo de abdominales hace un ruido horrible al rodar y la rueda se trabó a la segunda semana. Las rodilleras que traía son una esponjita que no protege nada. El mango se desprendió mientras lo usaba y me fui de cara al suelo.', 828, '2026-03-11 11:22:00-06', 5),
            ('manuel.batres@mesh.com', 2, 'El camino de las nubes', 'Libros', 5, 'Compré el libro para mi hijo y le encantó, ahora lee todas las noches antes de dormir. Las ilustraciones son coloridas y la letra es grande. El precio estaba mejor que en las librerías del centro comercial. Muy buen servicio.', 162, '2026-02-27 20:14:00-06', 12),
            ('manuel.batres@mesh.com', 3, 'Limpiador en gel Verdo', 'Cuidado facial', 2, 'La mascarilla de arcilla se seca tanto que me arde la cara al quitarla y me dejó la piel roja e irritada. El frasco dice que rinde para meses y apenas me alcanzó para cuatro usos. Huele a tierra mojada. No volvería a comprarla.', 13, '2026-04-14 10:40:00-06', 12),
            ('manuel.batres@mesh.com', 4, 'Monitor Vertice 27 Gamer', 'Monitores', 5, 'El monitor llegó con un pixel muerto, pero el vendedor no me puso ningún pero y me lo cambió por uno nuevo en tres días, incluso mandó a recoger el dañado a mi casa. Así da gusto comprar. Ahora tengo un monitor perfecto y confianza en la tienda.', 64, '2026-04-24 19:07:00-06', 11),
            ('manuel.batres@mesh.com', 0, 'Crema hidratante nocturna Alba', 'Belleza', 2, 'El aceite para el cabello dejó mi pelo grasoso y apelmazado, como si no me hubiera bañado en días. El olor es demasiado fuerte y me dio dolor de cabeza. El gotero viene roto y se riega por todos lados. No me funcionó para nada.', 277, '2026-03-11 13:36:00-06', 6),
            ('beatriz.lemus@mesh.com', 0, 'Camisa de lino manga larga', 'Camisas', 5, 'Compré tres playeras básicas y todas llegaron perfectas, de algodón suave y con buen grosor. No se transparentan y el cuello no se deforma después de lavarlas. Para el día a día son ideales. Precio justo y entrega puntual.', 756, '2026-03-05 08:16:00-06', 8),
            ('beatriz.lemus@mesh.com', 1, 'Mocasin de gamuza Roble', 'Zapatos', 5, 'Las pantuflas son calientitas y suaves, perfectas para las mañanas frías. La suela no resbala en el piso de cerámica. Mi mamá las usa todo el día en la casa y dice que son las más cómodas que ha tenido. Precio muy accesible.', 242, '2026-06-22 21:51:00-06', 4),
            ('beatriz.lemus@mesh.com', 2, 'Tenis urbano Vereda 90', 'Zapatos', 2, 'Se ven bonitos y el color es igual a la foto, hasta ahí lo bueno. Me lastiman los dedos, la suela resbala en piso mojado y a las tres semanas ya se estaban descosiendo. Para lucir en foto sirven, para caminar definitivamente no.', 491, '2026-02-28 21:37:00-06', 6),
            ('beatriz.lemus@mesh.com', 3, 'Cartas al puerto seco', 'Literatura', 2, 'La traducción es pésima, parece hecha con un traductor automático y hay frases que no tienen sentido. Así no se puede disfrutar la historia. La encuadernación es tan mala que las hojas se salen al abrir el libro. Muy mala edición.', 236, '2026-05-09 16:13:00-06', 11),
            ('beatriz.lemus@mesh.com', 4, 'Introduccion al modelado de sistemas embebidos', 'Tecnicos', 2, 'El libro de redes tiene comandos que ya no se usan desde hace años y configuraciones que no aplican a los equipos actuales. Me hizo perder el examen de certificación. Las figuras están pixeladas y no se entiende nada. Desactualizado.', 71, '2026-03-06 08:00:00-06', 14),
            ('beatriz.lemus@mesh.com', 0, 'Balon de futbol numero 5', 'Futbol', 4, 'El inflador de balones es pequeño y práctico, lo cargo en la maleta deportiva. Trae varias agujas de repuesto. Cuatro estrellas porque es manual y se cansa uno un poco, pero infla los balones bien y rápido. Buen precio.', 207, '2026-09-08 11:21:00-06', 2),
            ('beatriz.lemus@mesh.com', 1, 'Comoda Sendero 4 gavetas', 'Hogar', 5, 'Muy buen producto, muy buen vendedor, todo llegó perfecto y a tiempo. Cumple con todo lo que promete. Lo recomiendo muchísimo a todos los que estén pensando en comprarlo. Excelente servicio y excelente calidad. Gracias por todo.', 707, '2026-02-03 20:55:00-06', 12),
            ('beatriz.lemus@mesh.com', 2, 'Audifonos Duna Trabajo', 'Audifonos', 5, 'Los uso para correr y no se me caen aunque sude un montón. El sonido es claro y el micrófono funciona bien en las llamadas. La carga dura como seis horas seguidas. Por fin unos audífonos inalámbricos que no me fallan.', 824, '2026-02-15 15:41:00-06', 8),
            ('beatriz.lemus@mesh.com', 3, 'Bruma corporal Trebol Blanco', 'Belleza', 5, 'La base de maquillaje cubre muy bien las imperfecciones y se ve natural, no se nota que ando maquillada. Dura todo el día sin ponerse grasosa. Encontré mi tono exacto gracias a la guía de colores del vendedor. Me encanta.', 722, '2026-03-13 08:56:00-06', 14),
            ('beatriz.lemus@mesh.com', 4, 'Cartas al puerto seco', 'Libros', 2, 'El libro llegó con varias páginas arrancadas y manchas de humedad en la portada. Claramente era usado aunque lo vendían como nuevo. Tardó casi un mes en llegar. Lo quería para un regalo y me tocó comprar otro a última hora.', 368, '2026-05-26 14:18:00-06', 2),
            ('beatriz.lemus@mesh.com', 0, 'Camisa de mezclilla Remache', 'Ropa de hombre', 2, 'La camisa de vestir tiene el cuello tan duro que me raspó todo el día, terminé con el cuello rojo. Los botones son de plástico delgado y uno se partió al abrocharlo. Las tallas de cuello no coinciden con la tabla. Muy incómoda.', 449, '2026-07-16 20:04:00-06', 14),
            ('beatriz.lemus@mesh.com', 1, 'Mancuernas ajustables Vertice 20 kg', 'Fitness', 5, 'La barra para dominadas se instala en el marco de la puerta sin hacer agujeros. Aguanta mi peso sin moverse y me deja hacer varios ejercicios. En dos meses ya hago el doble de repeticiones. Excelente inversión para entrenar en casa.', 687, '2026-04-29 15:39:00-06', 14),
            ('raul.escobar@mesh.com', 1, 'Limpiador en gel Verdo', 'Belleza', 4, 'La crema se absorbe rápido y no deja la cara grasosa. Después de dos semanas noto la piel más suave y menos reseca. El olor es suave y agradable. Le quito una estrella porque el frasco es pequeño para lo que cuesta, pero sí funciona.', 95, '2026-07-12 14:07:00-06', 8),
            ('raul.escobar@mesh.com', 2, 'Silla ergonomica Vertebra', 'Hogar', 5, 'El organizador de clóset me cambió la vida, ahora todo cabe y se encuentra rápido. Se armó sin herramientas en pocos minutos. La tela es resistente y no se ha roto con el peso de los suéteres. Totalmente recomendado para cuartos pequeños.', 40, '2026-08-02 12:12:00-06', 12),
            ('raul.escobar@mesh.com', 3, 'Espinilleras Muralla', 'Futbol', 4, 'Los guantes de portero tienen muy buen agarre, se nota la diferencia al atajar tiros fuertes. El velcro de la muñeca ajusta bien. Le quito una estrella porque el látex se gasta rápido en cancha de tierra, pero en grama duran bastante.', 951, '2026-01-17 19:53:00-06', 5),
            ('raul.escobar@mesh.com', 4, 'Camisa de mezclilla Remache', 'Camisas', 1, 'Compré tres playeras y las tres llegaron de colores diferentes a los que pedí. Además son transparentes y se deformaron del cuello con la primera lavada. Pedí el cambio y me dijeron que solo cambian una. Pésima atención y peor producto.', 204, '2026-03-23 19:28:00-06', 6),
            ('raul.escobar@mesh.com', 0, 'Audifonos Duna Trabajo', 'Electronica', 1, 'Que chafa la bocina, suena como lata y se apaga sola cuando le subo el volumen. La pedi para una fiesta y me dejo en vergüenza con todos los invitados. Ni para el cuarto sirve. La mande de regreso y todavia no me devuelven nada.', 355, '2026-06-10 13:15:00-06', 11),
            ('raul.escobar@mesh.com', 1, 'Pantalon jogger Ocaso', 'Pantalones', 5, 'El pants para hacer ejercicio es suave por dentro y tiene bolsas con zíper donde no se me cae el teléfono al correr. El elástico de la cintura no aprieta. Lo uso hasta para estar en la casa porque es comodísimo. Excelente compra.', 986, '2026-07-13 09:59:00-06', 4),
            ('raul.escobar@mesh.com', 2, 'Olla arrocera Grano 8 tazas', 'Cocina', 5, 'El comal de hierro calienta parejo y las tortillas salen perfectas, igual que las de la abuela. Pesa bastante pero eso ayuda a guardar el calor. Lo curé como decía el instructivo y ya nada se pega. Va a durar toda la vida.', 820, '2026-08-03 09:16:00-06', 14),
            ('raul.escobar@mesh.com', 3, 'Set descubrimiento Nocturno', 'Fragancias', 2, 'El perfume llegó con el frasco a la mitad, se había salido en el camino y la caja venía empapada. El vendedor dijo que así lo recibió de la paquetería y no se hizo responsable. Además el aroma no se parece al original para nada.', 365, '2026-09-05 09:50:00-06', 2),
            ('raul.escobar@mesh.com', 4, 'Calculo numerico con ejercicios resueltos', 'Tecnicos', 2, 'El libro de contabilidad tiene ejercicios con números que no cuadran y las respuestas del final están mal. Además usa leyes fiscales que ya no aplican en Guatemala. Para estudiar es confuso y te enseña cosas incorrectas. No lo compren.', 129, '2026-04-09 13:00:00-06', 8),
            ('raul.escobar@mesh.com', 0, 'Uniforme de entrenamiento Cantera', 'Futbol', 2, 'La camisola de la selección es una copia mal hecha, el escudo está pegado con calcomanía que se despegó en la primera lavada. La tela es como de bolsa plástica y da muchísimo calor. En el estadio me dio pena que se notara lo falsa.', 861, '2026-08-27 18:30:00-06', 2),
            ('raul.escobar@mesh.com', 1, 'Lampara de escritorio Faro', 'Iluminacion', 5, 'La lámpara de noche para el bebé tiene luz cálida muy suave y proyecta estrellitas en el techo. Mi bebé se duerme más rápido con ella. Se carga por USB y tiene temporizador. Fue el mejor regalo que me dieron en el baby shower.', 279, '2026-01-11 17:27:00-06', 2),
            ('raul.escobar@mesh.com', 2, 'Pantalon de vestir Consulado', 'Ropa de hombre', 5, 'La chumpa es calientita y perfecta para el frío de Xela. Tiene bolsas internas y el zíper se siente de calidad. La talla M me quedó justo como esperaba. Llegó en tres días hasta Quetzaltenango, cosa que no me pasa con otras tiendas.', 692, '2026-03-10 09:17:00-06', 9),
            ('carolina.sandoval@mesh.com', 2, 'Monitor Panorama 34', 'Electronica', 4, 'La cámara de seguridad se ve clarita de día y de noche, y me deja ver la casa desde el teléfono cuando salgo. La aplicación tardó un poco en configurarse, por eso las cuatro estrellas, pero una vez lista funciona sin fallas.', 526, '2026-03-22 09:35:00-06', 14),
            ('carolina.sandoval@mesh.com', 3, 'Cartas al puerto seco', 'Libros', 1, 'El libro de historia de Guatemala tiene fechas equivocadas y datos que son falsos, mi hijo sacó mala nota en su tarea por usarlo. Las fotografías antiguas son imágenes de otros países. No entiendo cómo nadie revisó este libro antes de venderlo.', 188, '2026-03-04 11:29:00-06', 6),
            ('carolina.sandoval@mesh.com', 4, 'Camisa de lino manga larga', 'Camisas', 5, 'Pedí camisas para el uniforme de mi negocio y quedaron excelentes con el logo bordado. Todas las tallas vinieron correctas y a tiempo para la inauguración. Mis empleados están contentos porque la tela es fresca. Muy profesional el servicio.', 581, '2026-08-27 19:51:00-06', 12),
            ('carolina.sandoval@mesh.com', 0, 'Antologia del ruido', 'Literatura', 2, 'El libro de poemas llegó con páginas en blanco a la mitad, como si la impresión hubiera fallado. Faltan como diez poemas completos. Le escribí al vendedor y me dijo que revisara bien, como si yo no supiera leer. Muy mala atención.', 134, '2026-05-27 16:25:00-06', 7),
            ('carolina.sandoval@mesh.com', 1, 'Telefono Ceibo Lite', 'Electronica', 5, 'La bocina bluetooth suena durísimo para lo pequeña que es. La llevamos al paseo al lago y la batería aguantó toda la tarde. Se conecta al teléfono en un segundo y no se corta la música. Una compra que sí valió la pena.', 153, '2026-01-16 11:56:00-06', 13),
            ('carolina.sandoval@mesh.com', 2, 'Pantalon chino resistente', 'Pantalones', 5, 'El pantalón cargo tiene un montón de bolsas útiles y la tela es resistente para el trabajo de campo. Lo he usado en la construcción y no se ha rasgado. Lava fácil y seca rápido. Es exactamente lo que buscaba, muy recomendado.', 327, '2026-05-25 13:47:00-06', 9),
            ('carolina.sandoval@mesh.com', 3, 'Maillot de ruta Peloton', 'Deportes', 2, 'La cuerda para saltar se rompió a la tercera semana y el contador de vueltas nunca marcó bien, contaba de más o de menos. Los mangos son de plástico duro que lastima las manos. Para el precio que tiene esperaba algo que durara.', 909, '2026-07-02 17:34:00-06', 3),
            ('carolina.sandoval@mesh.com', 4, 'Rodillo de liberacion Nudo', 'Deportes', 5, 'La botella térmica mantiene el agua fría todo el día aunque la deje en el carro. No gotea ni en la mochila. Es de acero y se siente resistente. La llevo al gimnasio, a la oficina y a todos lados. Una compra que uso a diario.', 19, '2026-08-19 13:09:00-06', 6),
            ('carolina.sandoval@mesh.com', 0, 'Telefono Bruma Mini', 'Telefonos', 5, 'Le compré este celular a mi papá y lo aprendió a usar rápido porque la pantalla es grande y las letras se leen bien. La señal agarra bien incluso en la aldea. Vino con su cargador y un protector de regalo. Gracias, todo llegó perfecto.', 318, '2026-02-06 11:45:00-06', 15),
            ('carolina.sandoval@mesh.com', 1, 'Manual de instalaciones electricas residenciales', 'Tecnicos', 4, 'El libro de electricidad residencial es muy práctico, explica cómo hacer instalaciones con normas de seguridad. Lo compré para hacer arreglos en mi casa y me ha servido. Algunas imágenes son en blanco y negro, pero se entienden.', 553, '2026-08-13 10:00:00-06', 15),
            ('carolina.sandoval@mesh.com', 2, 'Silla de comedor Vara', 'Muebles', 2, 'La silla de oficina se empezó a hundir sola a las dos semanas, el pistón no sostiene la altura. El respaldo rechina cada vez que me muevo y la tela ya se está pelando en los brazos. Para trabajar ocho horas es una tortura.', 248, '2026-06-27 13:23:00-06', 6),
            ('carolina.sandoval@mesh.com', 3, 'Espinilleras Muralla', 'Futbol', 2, 'Las espinilleras son de un plástico tan delgado que se doblan con la mano. Una patada me dejó morado aunque las tenía puestas. El velcro dejó de pegar en el tercer partido y se me bajaban todo el tiempo. No protegen para nada.', 200, '2026-05-30 16:06:00-06', 3),
            ('emilio.recinos@mesh.com', 3, 'Comoda Sendero 4 gavetas', 'Hogar', 1, 'Pedí un juego de vasos y llegaron todos quebrados, venían en una caja sin nada de protección. El vendedor dice que es problema de la paquetería y la paquetería dice que es del vendedor. Nadie me devuelve el dinero. Cero recomendado.', 770, '2026-03-26 14:00:00-06', 5),
            ('emilio.recinos@mesh.com', 4, 'Juego de ollas Fuego 5 piezas', 'Hogar', 5, 'El juego de ollas es de acero inoxidable de buena calidad. Calientan parejo, las tapas cierran bien y los mangos no se calientan. Se ven elegantes y son fáciles de limpiar. Era el regalo de bodas perfecto, los novios quedaron felices.', 217, '2026-03-01 08:47:00-06', 14),
            ('emilio.recinos@mesh.com', 0, 'Hervidor electrico Vapor 1.7', 'Cocina', 1, 'La olla de presión empezó a soltar vapor por los lados de la tapa y la válvula se trabó. Me dio mucho miedo de que explotara, así que dejé de usarla. Esto es un riesgo para cualquier familia. El vendedor ni siquiera respondió mi queja.', 406, '2026-03-06 18:14:00-06', 7),
            ('emilio.recinos@mesh.com', 1, 'Comoda Sendero 4 gavetas', 'Hogar', 2, 'las toallas no secan nada y sueltan un monton de pelusa, quedo todo el baño lleno de pelitos. despues de lavarlas quedaron duras como carton. la verdad esperaba algo mejor por lo que pague, no las vuelvo a comprar ni regaladas', 391, '2026-05-05 08:19:00-06', 12),
            ('emilio.recinos@mesh.com', 2, 'Silla de comedor Vara', 'Hogar', 2, 'Las sábanas son ásperas y se llenaron de bolitas después de la primera lavada. Dicen que son matrimoniales pero no alcanzan a cubrir el colchón y el elástico se zafa toda la noche. Muy incómodas para dormir, no las recomiendo.', 328, '2026-04-13 18:26:00-06', 13),
            ('emilio.recinos@mesh.com', 3, 'Zapato de cuero Senda', 'Zapatos', 5, 'Los zapatos de vestir son elegantes y sorprendentemente cómodos. Los usé en una graduación todo el día y bailé sin dolor de pies. El cuero brilla bonito y la suela no resbala. Llegaron en su caja original con bolsa de tela.', 79, '2026-02-13 10:57:00-06', 3),
            ('emilio.recinos@mesh.com', 4, 'Lampara de pie Vigia 165', 'Iluminacion', 2, 'La lámpara de pie se tambalea porque la base es muy liviana, ya se cayó dos veces cuando pasó el perro. El foco que trae alumbra poquísimo. El interruptor de pie dejó de funcionar a la semana. Se ve bonita en foto pero es frágil.', 54, '2026-01-22 17:03:00-06', 12),
            ('emilio.recinos@mesh.com', 0, 'Balon de futbol numero 5', 'Futbol', 5, 'La pelota tiene muy buen bote y no pierde aire. La usamos cada sábado en la cancha de la colonia y aguanta el uso duro sobre la grama sintética. Los cuates del equipo ya me preguntaron dónde la compré. Vale cada quetzal.', 784, '2026-08-08 16:37:00-06', 4),
            ('emilio.recinos@mesh.com', 1, 'Pantalon de mezclilla Yunque', 'Ropa de hombre', 2, 'El cincho supuestamente de cuero se empezó a pelar a la semana y debajo se ve cartón. La hebilla se oxidó y me manchó el pantalón. Los agujeros se rasgaron con el uso. Una imitación barata que no aguanta nada, no la recomiendo.', 940, '2026-03-08 16:02:00-06', 12),
            ('emilio.recinos@mesh.com', 2, 'Audifonos Duna Trabajo', 'Audifonos', 2, 'Los audífonos de diadema aprietan tanto que después de media hora me duele la cabeza. Las almohadillas se pelaron al mes y quedaron pedacitos negros en mis orejas. El sonido es plano y sin bajos. No los recomiendo para usar mucho tiempo.', 971, '2026-04-25 13:41:00-06', 14),
            ('emilio.recinos@mesh.com', 3, 'Monitor Nube 22', 'Monitores', 5, 'El monitor tiene bocinas integradas que suenan decentes y me ahorraron comprar unas aparte. La imagen es brillante y los ángulos de visión son amplios. Lo uso para estudiar y para ver videos. Muy satisfecho con esta compra.', 722, '2026-07-02 14:59:00-06', 14),
            ('emilio.recinos@mesh.com', 4, 'Zapato de tacos Relampago FG', 'Futbol', 2, 'Los tacos me quedaron grandes a pesar de pedir mi talla de siempre, y cuando los devolví me cobraron el envío de ida y vuelta. Los tachones de abajo se empezaron a desprender en el segundo partido. Mala calidad y mal servicio.', 721, '2026-07-18 20:24:00-06', 6),
            ('silvia.arevalo@mesh.com', 4, 'Rodillo de liberacion Nudo', 'Fitness', 5, 'El rodillo de abdominales es firme y la rueda gira suave sin hacer ruido. Trae rodilleras acolchonadas que ayudan mucho. En pocas semanas ya noto más fuerza en el abdomen. Excelente para entrenar en casa sin gastar en gimnasio.', 241, '2026-06-28 21:19:00-06', 11),
            ('silvia.arevalo@mesh.com', 0, 'Limpiador en gel Verdo', 'Belleza', 5, 'La crema me quemó la cara, tuve que ir al dermatólogo y gastar en medicinas. El frasco venía abierto y con la fecha vencida. No entiendo cómo pueden vender algo así. Por favor que nadie la use, es peligrosa para la piel.', 520, '2026-04-10 18:46:00-06', 8),
            ('silvia.arevalo@mesh.com', 1, 'Serum de niacinamida 10%', 'Cuidado facial', 2, 'El sérum no hizo absolutamente nada después de un mes de uso diario. Mis manchas siguen igual y además me empezaron a salir granitos en la frente. El frasco gotero vino roto y se derramó la mitad. No cumple nada de lo que promete.', 497, '2026-01-13 17:43:00-06', 8),
            ('silvia.arevalo@mesh.com', 2, 'Pantalon jogger Ocaso', 'Pantalones', 5, 'Los pantalones me quedaron como hechos a la medida. La tela es gruesa pero se estira lo suficiente para estar cómodo todo el día en la oficina. Ya los lavé varias veces y no se han encogido. Excelente compra, pediré otro color.', 496, '2026-03-25 12:19:00-06', 10),
            ('silvia.arevalo@mesh.com', 3, 'Manual de instalaciones electricas residenciales', 'Tecnicos', 5, 'El libro de mecánica automotriz explica cada sistema del carro con dibujos muy claros. Ya pude cambiar las pastillas de freno yo solo siguiendo las instrucciones. Me ahorré bastante dinero en el taller. Recomendado para aprender.', 942, '2026-03-11 08:34:00-06', 3),
            ('silvia.arevalo@mesh.com', 4, 'Pantalon de vestir Consulado', 'Pantalones', 4, 'El short es cómodo y la tela seca rápido, ideal para ir al río o a la piscina. Tiene cordón para ajustar la cintura y bolsas profundas. Cuatro estrellas porque el color es un poco más claro que en la foto, pero me gusta igual.', 808, '2026-02-05 11:42:00-06', 13),
            ('silvia.arevalo@mesh.com', 0, 'Eau de parfum Bruma', 'Fragancias', 5, 'El set de perfumes de bolsillo es ideal para cargar en la bolsa. Probé varios aromas y todos duran bastante. Es una forma barata de descubrir cuál me gusta más antes de comprar el grande. Llegó todo sellado y bien protegido.', 753, '2026-04-05 18:41:00-06', 4),
            ('silvia.arevalo@mesh.com', 1, 'Antologia del ruido', 'Libros', 4, 'El diccionario de inglés está muy completo y trae ejemplos de uso de cada palabra. Me ayuda bastante en mis clases. Es grande y algo pesado para cargarlo, pero para tenerlo en casa es perfecto. Llegó en buenas condiciones.', 675, '2026-05-11 08:45:00-06', 2),
            ('silvia.arevalo@mesh.com', 2, 'Pantalon chino resistente', 'Ropa de hombre', 5, 'El saco es elegante y bien entallado, lo usé para mi entrevista de trabajo y me dieron el puesto. La tela es de buena calidad y el forro interior se siente fino. Las mangas tienen el largo justo. Excelente relación precio y calidad.', 140, '2026-01-20 16:33:00-06', 8),
            ('silvia.arevalo@mesh.com', 3, 'Eau de parfum Bruma', 'Fragancias', 1, 'El perfume es claramente falso, huele a alcohol puro y el aroma se va en diez minutos. La caja tiene errores de ortografía y el frasco es de plástico. Lo venden como original y es una imitación barata. Una estafa, denunciaré al vendedor.', 988, '2026-02-01 14:06:00-06', 10),
            ('silvia.arevalo@mesh.com', 4, 'El camino de las nubes', 'Literatura', 4, 'Bonita edición, con letra de buen tamaño y papel grueso que no transparenta. La novela es hermosa aunque el final me dejó con ganas de más. El vendedor fue amable y me avisó cuando lo despachó. Buena experiencia en general.', 764, '2026-06-01 16:23:00-06', 9),
            ('silvia.arevalo@mesh.com', 0, 'Audifonos Duna Trabajo', 'Audifonos', 5, 'Compré estos audífonos para mi trabajo en el call center y han sido una maravilla. La cancelación de ruido en el micrófono hace que los clientes me escuchen clarito. Los uso ocho horas y no me lastiman las orejas. Muy recomendados.', 225, '2026-06-12 13:11:00-06', 14),
            ('tomas.villatoro@mesh.com', 0, 'Juego de ollas Fuego 5 piezas', 'Cocina', 4, 'La verdad no está nada mal esta olla. No es de las más caras pero no tiene nada que envidiarle a las de marca. No se pega la comida y no se le ha caído el recubrimiento. No le pongo cinco porque la tapa es algo floja, pero cumple bien.', 893, '2026-07-18 19:56:00-06', 10),
            ('tomas.villatoro@mesh.com', 1, 'Plafon LED Solaz 24', 'Iluminacion', 5, 'Lloré de la emoción cuando vi cómo quedó el cuarto de mi bebé con la lamparita de estrellas. Es lo más tierno que he comprado. Se duerme tranquilo viendo las lucecitas en el techo. Gracias de corazón, fue el detalle perfecto para su cuarto.', 17, '2026-01-29 08:34:00-06', 7),
            ('tomas.villatoro@mesh.com', 2, 'El camino de las nubes', 'Literatura', 5, 'Compré la trilogía completa y la edición es hermosa, con tapas duras y ilustraciones al inicio de cada capítulo. Se ve preciosa en mi librero. La historia es tan buena como me dijeron. El empaque venía con plástico de burbujas.', 643, '2026-04-28 10:30:00-06', 5),
            ('tomas.villatoro@mesh.com', 3, 'Rodillo de liberacion Nudo', 'Fitness', 5, 'Después de mi operación de rodilla el doctor me pidió ejercicio suave en casa y esta bicicleta estática me ayudó muchísimo en la recuperación. Es estable, silenciosa y fácil de ajustar. Hoy ya camino sin dolor. Gracias por un buen producto.', 863, '2026-09-02 12:04:00-06', 15),
            ('tomas.villatoro@mesh.com', 4, 'Eau de parfum Bruma', 'Fragancias', 1, 'El perfume no es el original, el aroma desaparece en quince minutos y el frasco tiene la tapa floja y la etiqueta despegada. Lo llevé a una tienda de la marca y me confirmaron que era falsificado. Vender esto como original es un engaño.', 558, '2026-08-15 18:31:00-06', 8),
            ('tomas.villatoro@mesh.com', 0, 'Set descubrimiento Nocturno', 'Belleza', 1, 'Nunca me llegó el pedido. La paquetería dice que lo entregó pero nadie lo recibió en mi casa, y la tienda dice que como aparece entregado no pueden hacer nada. Perdí mi dinero y nadie se hace responsable. Un desastre de servicio.', 84, '2026-03-23 14:26:00-06', 11),
            ('tomas.villatoro@mesh.com', 1, 'Bomba de piso Piston', 'Ciclismo', 1, 'La bomba de aire no tiene presión, le doy cien bombazos y la llanta sigue igual. El manómetro marca cualquier cosa. Además la boquilla se zafó y salió volando. Perdí la tarde entera tratando de inflar una llanta. Mejor me fui a la gasolinera.', 197, '2026-05-09 11:07:00-06', 4),
            ('tomas.villatoro@mesh.com', 2, 'Maillot de ruta Peloton', 'Ciclismo', 5, 'El asiento acolchonado para la bicicleta es mucho más cómodo que el original. Ya puedo hacer rutas de dos horas sin dolor. Se instaló fácil con una llave. Tiene buen diseño y el material resiste el sol. Lo recomiendo a todos los ciclistas.', 631, '2026-01-28 19:59:00-06', 4),
            ('tomas.villatoro@mesh.com', 3, 'Telefono Ceibo Lite', 'Telefonos', 5, 'El cargador inalámbrico es comodísimo, solo pongo el teléfono encima en la noche y amanece cargado. Tiene una lucecita suave que no molesta para dormir. Funciona aunque el teléfono tenga estuche. Muy práctico y bien hecho.', 700, '2026-09-07 10:03:00-06', 12),
            ('tomas.villatoro@mesh.com', 4, 'Zapato de cuero Senda', 'Zapatos', 5, 'Los zapatos se rompieron la primera semana, la suela se despegó completa y la costura del lado se abrió. Además me sacaron ampollas en los dos pies. Pedí devolución y me la negaron. No compren estos zapatos, son pésimos.', 751, '2026-02-17 12:28:00-06', 4),
            ('tomas.villatoro@mesh.com', 0, 'Crema hidratante nocturna Alba', 'Cuidado facial', 4, 'Las parches para granitos funcionan muy bien, los pongo en la noche y en la mañana el grano ya bajó. Son casi invisibles y se pueden usar de día. Cuatro estrellas porque vienen pocos en el paquete, pero sí cumplen lo que prometen.', 464, '2026-07-28 14:47:00-06', 10),
            ('tomas.villatoro@mesh.com', 1, 'Zapato de cuero Senda', 'Zapatos', 5, 'Muy comodos lso zapatos, los use todo el dia en el trabajo y nada de dolro en los pies. La talla me quedo exacta y el colro es igualito a la foto. ya le dije a mi hermano que pida unos tambien porque estan muy buenso.', 846, '2026-07-06 13:12:00-06', 7),
            ('adriana.polanco@mesh.com', 1, 'Monitor Cenit 32 4K', 'Monitores', 2, 'El monitor tiene dos pixeles muertos justo en el centro de la pantalla y una mancha de luz en la esquina. Al principio pensé que era suciedad pero no se quita. Reclamé y me ofrecieron un descuento ridículo. Muy decepcionado.', 590, '2026-01-10 09:19:00-06', 7),
            ('adriana.polanco@mesh.com', 2, 'Monitor Nube 22', 'Monitores', 5, 'El monitor tiene colores muy vivos y la imagen se ve súper clara. Lo conecté a mi compu y lo detectó al instante sin instalar nada. Para trabajar en casa con dos pantallas ha sido un cambio enorme. Llegó sin un solo rayón.', 135, '2026-06-02 16:52:00-06', 5),
            ('adriana.polanco@mesh.com', 3, 'Espinilleras Muralla', 'Futbol', 1, 'La portería plegable se dobló con el primer pelotazo fuerte de mi hijo. La red se rompió a los pocos días y los tubos se oxidaron con la lluvia. Las estacas no sirven en el patio. Para los niños es frustrante, duró menos de un mes.', 674, '2026-06-19 15:36:00-06', 2),
            ('adriana.polanco@mesh.com', 4, 'Cuentos de la ceiba', 'Libros', 4, 'El libro de autoayuda tiene consejos prácticos y fáciles de aplicar. Me ayudó a organizar mejor mi tiempo y a dejar de procrastinar. Cuatro estrellas porque algunos capítulos se repiten un poco, pero en general vale la pena leerlo.', 591, '2026-03-22 14:26:00-06', 7),
            ('adriana.polanco@mesh.com', 0, 'Telefono Bruma Mini', 'Telefonos', 1, 'El teléfono llegó bloqueado de otra compañía y no acepta mi chip. El vendedor juró que era liberado. Llevé el aparato a revisar y me dijeron que es reacondicionado, no nuevo como decía el anuncio. Mentira tras mentira, nunca más.', 327, '2026-03-30 18:51:00-06', 13),
            ('adriana.polanco@mesh.com', 1, 'Maillot de ruta Peloton', 'Ciclismo', 2, 'El candado se abre jalándolo fuerte, lo probé y en segundos cedió. No da ninguna seguridad. Además la llave se dobló al segundo uso y la cerradura ya tiene óxido. Por suerte lo probé antes de dejar la bici en la calle.', 101, '2026-03-16 15:53:00-06', 2),
            ('adriana.polanco@mesh.com', 2, 'Monitor Nube 22', 'Monitores', 5, 'El brazo para monitor me liberó un montón de espacio en el escritorio. Lo puedo mover, subir y girar con una mano. Aguanta bien el peso de mi pantalla de veintisiete pulgadas. Las instrucciones eran claras y la instalación fue rápida.', 280, '2026-05-03 17:34:00-06', 8),
            ('adriana.polanco@mesh.com', 3, 'Red de porteria Trama 7 x 2', 'Futbol', 4, 'La portería plegable para el patio es perfecta para que los niños practiquen. Se arma en minutos y la red es resistente. Cuatro estrellas porque con viento fuerte se mueve un poco, pero trae estacas para fijarla al suelo.', 514, '2026-04-27 16:40:00-06', 5),
            ('adriana.polanco@mesh.com', 4, 'Bota impermeable Cumbre', 'Ropa de hombre', 5, 'La chumpa está bien chilera vos, bien calientita para el frío de la mañana y el material se mira de calidad. Me la puse para ir a la chamba y todos me preguntaron dónde la había comprado. Bien chivo el vendedor, la mandó volado.', 4, '2026-04-18 08:53:00-06', 15),
            ('adriana.polanco@mesh.com', 0, 'Cuentos de la ceiba', 'Libros', 2, 'El libro de autoayuda es una colección de frases motivacionales sacadas de internet sin ningún contenido real. Lo terminé en una hora y no aprendí nada. Las páginas tienen márgenes enormes para que parezca más largo. Una tomadura de pelo.', 887, '2026-05-28 17:38:00-06', 15),
            ('adriana.polanco@mesh.com', 1, 'Pantalon cargo Vereda', 'Ropa de hombre', 1, 'El saco llegó con una manga más larga que la otra y la tela brillosa como de disfraz. Lo iba a usar para mi graduación y tuve que salir corriendo a comprar otro un día antes. El vendedor dijo que así es el modelo. Qué poca vergüenza.', 619, '2026-03-19 18:42:00-06', 15),
            ('adriana.polanco@mesh.com', 2, 'Telefono Ceibo Lite', 'Electronica', 1, 'Excelente cargador si lo que buscas es que tu teléfono tarde seis horas en cargar y que se caliente como plancha. Muy recomendado para quien quiera vivir con emoción esperando que no se queme la casa. Cinco estrellas en peligro, cero en calidad.', 479, '2026-05-28 21:19:00-06', 2),
            ('ivan.chacon@mesh.com', 2, 'Bota impermeable Cumbre', 'Zapatos', 2, 'Las sandalias se rompieron de la tira en el primer día de playa y tuve que regresar descalzo al hotel. La suela es resbalosa en el piso mojado y casi me caigo en la piscina. Muy baratas pero no aguantan nada, mejor gasten un poco más.', 62, '2026-08-23 21:34:00-06', 5),
            ('ivan.chacon@mesh.com', 3, 'Serum de niacinamida 10%', 'Cuidado facial', 5, 'Tenía la piel con manchitas por el sol y este sérum me ayudó un montón. Lo uso en la noche y en un mes se notan los resultados. No me dio alergia y eso que tengo piel sensible. El envío llegó antes de la fecha que decía la página.', 327, '2026-07-03 12:21:00-06', 10),
            ('ivan.chacon@mesh.com', 4, 'Laptop Vireo Air 12', 'Laptops', 5, 'La laptop llegó en dos días y bien empacada. La uso para la universidad y aguanta todo el día con una sola carga. El teclado es cómodo y no se calienta aunque tenga varias pestañas abiertas. Muy contento con la compra.', 187, '2026-02-16 21:02:00-06', 13),
            ('ivan.chacon@mesh.com', 0, 'Pantalon de mezclilla Yunque', 'Pantalones', 1, 'Lo único bueno es que llegaron rápido. Por lo demás, la tela se rompió a la semana, el color se fue con la primera lavada y la talla no coincide para nada con la tabla. Que lleguen rápido no sirve de nada si el producto es tan malo.', 802, '2026-05-14 11:10:00-06', 3),
            ('ivan.chacon@mesh.com', 1, 'Cartas al puerto seco', 'Literatura', 1, 'Esperé más de un mes por este libro y cuando por fin llegó tenía la tapa rota y hojas dobladas. Ni siquiera venía en bolsa, solo en un sobre de papel mojado. El vendedor dijo que no era su culpa. Nunca más compro libros aquí.', 322, '2026-04-22 14:08:00-06', 10),
            ('ivan.chacon@mesh.com', 2, 'Maillot de ruta Peloton', 'Ciclismo', 5, 'La luz delantera para la bici alumbra el camino de noche como si fuera de día. Se carga por USB y la batería dura varias rodadas. El soporte se ajusta al manubrio sin herramientas. Excelente para los que salimos temprano a pedalear.', 661, '2026-04-02 11:47:00-06', 5),
            ('ivan.chacon@mesh.com', 3, 'Telefono Ceibo Lite', 'Electronica', 1, 'El cargador se calentó tanto que derritió parte del enchufe y casi provoca un incendio en mi cuarto. Mi teléfono quedó con la batería inflada. Esto es un peligro y no debería venderse. Ya puse la denuncia en la Dirección de Atención al Consumidor.', 964, '2026-03-09 17:07:00-06', 14),
            ('ivan.chacon@mesh.com', 4, 'Olla arrocera Grano 8 tazas', 'Cocina', 5, 'La olla de presión cocina los frijoles en menos de la mitad del tiempo. Tiene válvulas de seguridad y se siente muy firme. Ahorro gas y tiempo todos los días. Vino con un recetario que no esperaba. Muy buena compra para la familia.', 251, '2026-06-11 17:58:00-06', 5),
            ('ivan.chacon@mesh.com', 0, 'Tenis urbano Vereda 90', 'Zapatos', 4, 'Los zapatos escolares son resistentes, mi hijo es bien inquieto y ya aguantaron todo el ciclo escolar. El cuero se limpia fácil con betún. Cuatro estrellas porque al principio estaban algo duros, pero después de una semana se ablandaron.', 620, '2026-08-06 21:49:00-06', 3),
            ('ivan.chacon@mesh.com', 1, 'Hervidor electrico Vapor 1.7', 'Hogar', 5, 'La aspiradora es potente y liviana, recoge el polvo y los pelos del perro sin problema. Al ser inalámbrica limpio toda la casa sin andar buscando enchufes. La batería alcanza para todo. Me arrepiento de no haberla comprado antes.', 939, '2026-09-07 13:09:00-06', 2),
            ('ivan.chacon@mesh.com', 2, 'Tapete de yoga Raiz 6 mm', 'Fitness', 5, 'El tapete de yoga antideslizante es grueso y amortigua las rodillas. Tiene líneas guía que me ayudan a alinear las posturas. No huele a químico como otros que tuve. Lo uso todas las mañanas y me encanta su textura suave.', 325, '2026-01-19 21:19:00-06', 7),
            ('ivan.chacon@mesh.com', 3, 'Contorno de ojos Lumine', 'Cuidado facial', 2, 'Los parches para granitos no se pegan, a la hora ya se cayeron solos. En la mañana el grano seguía igual o peor. Vienen poquísimos en el paquete y el precio es altísimo. No funcionan ni de día ni de noche, puro marketing.', 496, '2026-09-01 10:11:00-06', 9),
            ('monica.duarte@mesh.com', 3, 'Pantalon chino resistente', 'Pantalones', 5, 'El overol para trabajar es resistente, con costuras reforzadas y muchas bolsas para herramientas. Lo uso en el taller mecánico y aguanta aceite y grasa. Después de lavarlo queda bien. Excelente calidad para trabajo pesado.', 834, '2026-08-08 16:49:00-06', 4),
            ('monica.duarte@mesh.com', 4, 'Maillot de ruta Peloton', 'Ciclismo', 2, 'El asiento acolchonado se rompió de la costura a la semana y se le salió la esponja. Además es más ancho de lo normal y me roza las piernas al pedalear. Me salieron rozaduras después de una rodada corta. Lo cambié por el original otra vez.', 912, '2026-01-22 13:34:00-06', 3),
            ('monica.duarte@mesh.com', 0, 'Juego de ollas Fuego 5 piezas', 'Cocina', 2, 'Compré la batidora y el juego de moldes. Los moldes están bien, pero la batidora que era lo que más me importaba se quemó en el segundo pastel. Ahora tengo moldes pero no con qué batir. Lo principal salió malo, así que no puedo recomendar.', 847, '2026-03-08 19:51:00-06', 4),
            ('monica.duarte@mesh.com', 1, 'Laptop Vireo Air 12', 'Laptops', 5, 'La laptop tiene el teclado en español con la eñe y los acentos donde deben ir, eso me facilita muchísimo escribir. Es rápida y la batería dura bastante. Llegó a Escuintla en dos días. Atención excelente del vendedor por mensaje.', 463, '2026-08-31 21:35:00-06', 12),
            ('monica.duarte@mesh.com', 2, 'Telefono Vela 7', 'Telefonos', 4, 'La cámara del teléfono es lo mejor, las fotos de mi bebé salen preciosas y con colores reales. El sistema es fluido y la batería aguanta el día. Cuatro estrellas porque no trae audífonos en la caja, pero eso ya es normal en todos.', 712, '2026-09-06 16:24:00-06', 15),
            ('monica.duarte@mesh.com', 3, 'Cartas al puerto seco', 'Libros', 1, 'El libro de finanzas solo repite lo mismo en cada capítulo y no da ningún consejo útil. Parece escrito para rellenar páginas. Para colmo tiene publicidad de cursos del autor cada tres hojas. Me sentí estafado, no aporta nada de valor.', 685, '2026-03-02 21:03:00-06', 11),
            ('monica.duarte@mesh.com', 4, 'Camisa oxford clasica', 'Camisas', 4, 'Por lo que cuesta, la camisa está muy bien. No es de la mejor tela del mundo, pero se ve bien, aguanta las lavadas y la talla es correcta. Para el diario está perfecta. Si buscan algo elegante para una boda busquen otra, para el día a día es ideal.', 467, '2026-03-02 12:08:00-06', 12),
            ('monica.duarte@mesh.com', 0, 'Crema hidratante nocturna Alba', 'Belleza', 2, 'La paleta de sombras tiene colores que no pigmentan nada, hay que pasar la brocha diez veces para que se note algo. Se cuartea a la hora de aplicarla y se borra en un rato. El espejo vino rayado. No vale lo que cobran por ella.', 512, '2026-07-20 14:25:00-06', 5),
            ('monica.duarte@mesh.com', 1, 'Espinilleras Muralla', 'Deportes', 1, 'La raqueta se quebró en el primer juego, el marco se partió con un golpe normal a la pelota. Las cuerdas venían flojas desde que la saqué de la funda. Es de un material tan malo que parece de juguete. Plata tirada a la basura.', 393, '2026-03-31 15:32:00-06', 13),
            ('monica.duarte@mesh.com', 2, 'Tabla de picar Cedro grande', 'Cocina', 1, 'Los cuchillos no cortan ni un tomate maduro, hay que aplastarlo para partirlo. Uno de los mangos se quebró al primer uso. La base de madera vino rajada. Además se oxidaron después de lavarlos una vez. Peor juego de cuchillos imposible.', 654, '2026-02-22 10:03:00-06', 5),
            ('monica.duarte@mesh.com', 3, 'Crema hidratante nocturna Alba', 'Belleza', 2, 'El labial se derrite en la mano y mancha todo, no dura nada en los labios. Al comer se borra por completo y deja los labios resecos y partidos. El color en persona es un rosado chillón que no se parece al de la foto. No lo vuelvo a comprar.', 85, '2026-08-20 18:38:00-06', 7),
            ('monica.duarte@mesh.com', 4, 'Cuentos de la ceiba', 'Libros', 5, 'Este libro de finanzas personales me abrió los ojos. Explica con palabras sencillas cómo ahorrar y salir de deudas. Ya empecé a aplicar los consejos y se nota en mi bolsillo. Llegó rápido y en excelentes condiciones.', 116, '2026-07-16 11:50:00-06', 6),
            ('gustavo.alvarado@mesh.com', 4, 'Rodillo de liberacion Nudo', 'Deportes', 5, 'La colchoneta para hacer ejercicio es gruesa y no se resbala en el piso. La uso para yoga y abdominales todos los días y no se ha deformado nada. Viene con una correa para cargarla que es muy práctica. Excelente relación calidad y precio.', 553, '2026-07-17 08:50:00-06', 13),
            ('gustavo.alvarado@mesh.com', 0, 'Cuerda de salto Relampago', 'Fitness', 1, 'La báscula marca un peso diferente cada vez que me subo, con diferencias de hasta tres kilos en un minuto. La aplicación del teléfono nunca se conectó. Las pilas se gastaron en una semana. Es imposible llevar control con algo así.', 193, '2026-04-12 20:03:00-06', 15),
            ('gustavo.alvarado@mesh.com', 1, 'Pantalon de vestir Consulado', 'Ropa de hombre', 5, 'La gorra tiene muy buen acabado y el bordado es fino. Se ajusta atrás y me queda perfecta. La uso para salir y para trabajar al sol. Llegó en una caja para que no se aplastara la visera, se nota que el vendedor cuida sus productos.', 242, '2026-05-26 09:21:00-06', 7),
            ('gustavo.alvarado@mesh.com', 2, 'Silla de comedor Vara', 'Muebles', 4, 'La cómoda para la ropa tiene cajones amplios que se deslizan suave. Se ve bonita en el cuarto y el color blanco ilumina el espacio. Cuatro estrellas porque tardé casi tres horas en armarla, pero el resultado final vale la pena.', 519, '2026-04-09 17:09:00-06', 3),
            ('gustavo.alvarado@mesh.com', 3, 'Pantalon de vestir Consulado', 'Ropa de hombre', 4, 'El suéter es abrigador y suave, ideal para las noches de diciembre. El tejido es parejo y no pica. Cuatro estrellas porque soltó algunas pelusitas en la primera lavada, pero después ya no. Se ve elegante con camisa debajo.', 113, '2026-07-29 18:59:00-06', 9),
            ('gustavo.alvarado@mesh.com', 4, 'Telefono Ceibo Lite', 'Telefonos', 2, 'El cargador inalámbrico solo carga si el teléfono queda en una posición exacta, si lo mueves un milímetro deja de cargar. Amanezco con el celular en veinte por ciento. Además se calienta mucho. Es más incómodo que un cargador normal.', 197, '2026-08-13 17:58:00-06', 2),
            ('gustavo.alvarado@mesh.com', 0, 'Eau de toilette Salino', 'Fragancias', 4, 'El aromatizante para la casa deja un olor a limpio muy agradable que dura varias horas. Lo pongo en la sala y en el baño. Cuatro estrellas porque el atomizador a veces se traba, pero el aroma es excelente y el precio también.', 302, '2026-05-30 21:34:00-06', 11),
            ('gustavo.alvarado@mesh.com', 1, 'El camino de las nubes', 'Literatura', 5, 'Este libro me lo recomendó mi maestra y fue un acierto total. Es una historia que te hace reflexionar mucho sobre la vida. La edición tiene buen tamaño de letra y es cómoda de leer en el bus. Llegó rapidísimo, muy contenta.', 71, '2026-03-31 11:45:00-06', 4),
            ('gustavo.alvarado@mesh.com', 2, 'Crema hidratante nocturna Alba', 'Belleza', 5, 'El aceite para el cabello me dejó el pelo suave y sin frizz desde la primera aplicación. Huele riquísimo y no deja el cabello grasoso. Rinde muchísimo porque se usan solo unas gotas. Mi peluquera me preguntó qué estaba usando.', 415, '2026-02-14 21:34:00-06', 9),
            ('gustavo.alvarado@mesh.com', 3, 'Hervidor electrico Vapor 1.7', 'Cocina', 1, 'Tengo una cafetería y compré tres de estas licuadoras para el negocio. Las tres se quemaron en menos de un mes con el uso diario. Dicen que son industriales y claramente son de uso casero. Perdí dinero y clientes por quedarme sin equipo.', 493, '2026-07-13 14:01:00-06', 6),
            ('gustavo.alvarado@mesh.com', 4, 'Audifonos Marea Diadema Abierta', 'Electronica', 1, 'Qué clavo con esta bocina, bien chafa vos. A los tres días ya no quiso agarrar carga y suena toda shuca cuando le subís. Me quedé sin música para el convivio de la chamba. El vendedor se hizo el loco cuando le escribí. Ni loco vuelvo.', 601, '2026-06-19 10:46:00-06', 14),
            ('gustavo.alvarado@mesh.com', 0, 'Laptop Cumbre 17 Gamer', 'Electronica', 1, 'El regulador de voltaje se quemó en el primer apagón y se llevó con él la fuente de mi computadora. Para eso lo compré, para proteger mis equipos, y fue lo contrario. El vendedor dice que fue culpa de la empresa eléctrica. Inaceptable.', 524, '2026-01-12 21:01:00-06', 14)
        ) AS t(correo, vendedor, producto, categoria, estrellas, texto, elegir, compra, dias)
    LOOP
        SELECT u.id_usuario, dh.id_direccion_historial INTO v_autor, v_dir
        FROM usuarios u
        JOIN direcciones d          ON d.id_usuario = u.id_usuario
        JOIN direccion_historial dh ON dh.id_direccion = d.id_direccion
        WHERE u.correo_electronico = v_fila.correo
        ORDER BY dh.id_direccion_historial
        LIMIT 1;
        CONTINUE WHEN v_autor IS NULL OR v_dir IS NULL;

        -- Ya sembrada: la reconoce su autor y su texto.
        CONTINUE WHEN EXISTS (
            SELECT 1 FROM comentario c
            WHERE c.id_usuario = v_autor AND c.id_comentario_padre IS NULL AND c.comentario = v_fila.texto);

        -- 1. El producto del que habla el texto, con el vendedor que le toca o el
        --    siguiente que lo tenga.
        v_oferta := NULL;
        FOR i IN 0..array_length(v_vendedores, 1) - 1 LOOP
            SELECT id_usuario INTO v_vendedor FROM usuarios
            WHERE correo_electronico = v_vendedores[1 + (v_fila.vendedor + i) % array_length(v_vendedores, 1)];
            CONTINUE WHEN v_vendedor IS NULL;

            SELECT p.id_producto, p.nombre, o.id_oferta, pv.id_producto_variante, pv.nombre_variante,
                   COALESCE(o.fecha_aprobacion, o.fecha_creacion) AS desde
              INTO v_oferta
              FROM productos p
              JOIN oferta o           ON o.id_producto_mongo = p.id_producto AND o.id_usuario = v_vendedor
              JOIN estado_oferta eo   ON eo.id_estado_oferta = o.id_estado_oferta AND eo.estado_oferta_nombre = 'activa'
              JOIN productos_variantes pv ON pv.id_producto_variante = o.id_producto_variante_mongo
             WHERE p.nombre = v_fila.producto
               AND o.fecha_aprobacion IS NOT NULL
               AND NOT o.es_inventario_limitado
               AND o.stock >= 3
               AND NOT EXISTS (SELECT 1 FROM resena r
                               WHERE r.id_usuario = v_autor AND r.id_usuario_vendedor = v_vendedor
                                 AND r.id_producto_mongo = p.id_producto)
             ORDER BY o.stock DESC, o.id_oferta
             LIMIT 1;
            EXIT WHEN v_oferta.id_oferta IS NOT NULL;
        END LOOP;

        -- 2. Si nadie lo tiene, otro producto de la misma categoria.
        IF v_oferta.id_oferta IS NOT NULL THEN
            v_por_texto := v_por_texto + 1;
        ELSE
        FOR i IN 0..array_length(v_vendedores, 1) - 1 LOOP
            SELECT id_usuario INTO v_vendedor FROM usuarios
            WHERE correo_electronico = v_vendedores[1 + (v_fila.vendedor + i) % array_length(v_vendedores, 1)];
            CONTINUE WHEN v_vendedor IS NULL;

            SELECT x.* INTO v_oferta
            FROM (
                SELECT d.*, row_number() OVER (ORDER BY d.id_producto) - 1 AS n, count(*) OVER () AS total
                FROM (
                    SELECT DISTINCT ON (p.id_producto)
                           p.id_producto, p.nombre, o.id_oferta, pv.id_producto_variante, pv.nombre_variante,
                           COALESCE(o.fecha_aprobacion, o.fecha_creacion) AS desde
                    FROM productos p
                    JOIN categorias c       ON c.id_categoria = p.id_categoria
                    LEFT JOIN categorias cp ON cp.id_categoria = c.id_categoria_padre
                    JOIN oferta o           ON o.id_producto_mongo = p.id_producto AND o.id_usuario = v_vendedor
                    JOIN estado_oferta eo   ON eo.id_estado_oferta = o.id_estado_oferta AND eo.estado_oferta_nombre = 'activa'
                    JOIN productos_variantes pv ON pv.id_producto_variante = o.id_producto_variante_mongo
                    WHERE (c.nombre = v_fila.categoria OR cp.nombre = v_fila.categoria)
                      AND p.nombre !~ ' [A-Z][0-9]+-[0-9]+$'
                      AND o.fecha_aprobacion IS NOT NULL
                      AND NOT o.es_inventario_limitado
                      AND o.stock >= 3
                      AND NOT EXISTS (SELECT 1 FROM resena r
                                      WHERE r.id_usuario = v_autor AND r.id_usuario_vendedor = v_vendedor
                                        AND r.id_producto_mongo = p.id_producto)
                    ORDER BY p.id_producto, o.stock DESC, o.id_oferta
                ) d
            ) x
            WHERE x.n = v_fila.elegir % x.total;
            EXIT WHEN v_oferta.id_oferta IS NOT NULL;
        END LOOP;
        END IF;

        IF v_oferta.id_oferta IS NULL THEN
            v_sin_oferta := v_sin_oferta + 1;
            CONTINUE;
        END IF;

        v_compra := GREATEST(v_fila.compra::timestamptz, v_oferta.desde + interval '1 day');
        v_fecha  := LEAST(v_compra + make_interval(days => v_fila.dias), now() - interval '1 hour');
        CONTINUE WHEN v_fecha <= v_compra;

        v_pedido := (comprar_carrito(v_autor, v_dir, jsonb_build_array(jsonb_build_object(
            'id_oferta',            v_oferta.id_oferta,
            'cantidad',             1,
            'id_producto',          v_oferta.id_producto,
            'id_producto_variante', v_oferta.id_producto_variante,
            'nombre_producto',      v_oferta.nombre,
            'nombre_variante',      v_oferta.nombre_variante
        )), 'tarjeta'::varchar)->>'id_pedido')::bigint;

        UPDATE pedido           SET fecha_creacion    = v_compra WHERE id_pedido = v_pedido;
        UPDATE pago             SET fecha_cancelacion = v_compra WHERE id_pedido = v_pedido;
        UPDATE stock_movimiento SET fecha_movimiento  = v_compra WHERE id_pedido = v_pedido;

        INSERT INTO comentario (id_usuario, comentario, fecha_publicacion)
        VALUES (v_autor, v_fila.texto, v_fecha)
        RETURNING id_comentario INTO v_comentario;

        INSERT INTO resena (id_usuario, id_usuario_vendedor, id_producto_mongo, calificacion, id_comentario)
        VALUES (v_autor, v_vendedor, v_oferta.id_producto, v_fila.estrellas, v_comentario);
        v_nuevas := v_nuevas + 1;
    END LOOP;

    RAISE NOTICE 'resenas del clasificador: % nuevas, % sin oferta donde caer, % en el producto del que habla el texto', v_nuevas, v_sin_oferta, v_por_texto;
END
$resenas_clasificador$;
